+            Some(("import-journals", sub)) => Some(Commands::ImportJournals {
+                path: sub
+                    .get_one::<String>("path")
+                    .map(PathBuf::from)
+                    .expect("required by clap"),
+            }),
+            Some(("assign-priority", sub)) => Some(Commands::AssignPriority {
