+                    Some(("write-defaults", _)) => ThemeCommands::WriteDefaults,
+                    _ => bail!("unsupported theme command"),
+                },
+            }),
+            Some((name, _)) => bail!("unsupported command: {name}"),
+            None => None,
+        };
+
+        Ok(Self {
+            json_file_path: matches.get_one::<String>("json-file-path").map(PathBuf::from),
+            sqlite_file_path: matches
