+fn apply_cli_overrides(mut cfg: EffectiveConfig, cli: &Cli) -> EffectiveConfig {
+    if let Some(path) = &cli.json_file_path {
+        cfg.json_backend_file_path = path.clone();
+        cfg.backend_type = BackendType::Json;
+    }
+    if let Some(path) = &cli.sqlite_file_path {
+        cfg.sqlite_backend_file_path = path.clone();
+        cfg.backend_type = BackendType::Sqlite;
+    }
+    if let Some(backend_type) = cli.backend_type {
+        cfg.backend_type = match backend_type {
+            BackendTypeArg::Json => BackendType::Json,
+            BackendTypeArg::Sqlite => BackendType::Sqlite,
+        };
+    }
+    if cli.json_file_path.is_some() {
