+pub fn sort_entries(entries: &mut [Entry]) {
+    entries.sort_by(|left, right| {
+        right
+            .date
+            .cmp(&left.date)
+            .then_with(|| right.priority.cmp(&left.priority))
+            .then_with(|| left.id.cmp(&right.id))
