+#[derive(Debug, Clone)]
+pub enum StartupAction {
+    None,
+    AssignPriorityDone,
+    ImportDone,
+    PersistentError { title: String, lines: Vec<String> },
+}
+
+pub fn run_app(config: EffectiveConfig, startup_action: StartupAction) -> Result<()> {
+    let store = BackendStore::from_effective_config(&config)?;
+    let mut entries = store.load_entries()?;
+    let mut app = App::new(config, store, entries, startup_action);
+    let mut terminal = setup_terminal()?;
+    let result = app.run(&mut terminal);
+    restore_terminal(&mut terminal)?;
+    result
+}
