+impl App {
+    fn new(
+        config: EffectiveConfig,
+        store: BackendStore,
+        mut entries: Vec<Entry>,
+        startup_action: StartupAction,
+    ) -> Self {
+        sort_entries(&mut entries);
+        let selected = if entries.is_empty() { None } else { Some(0) };
+        let (popup, transient_popup) = match startup_action {
+            StartupAction::None => (None, None),
+            StartupAction::AssignPriorityDone => (
+                None,
+                Some(TransientPopup {
+                    lines: vec!["Assigning Priority to Journals...".to_string()],
+                    expires_at: Instant::now() + Duration::from_millis(350),
+                }),
+            ),
+            StartupAction::ImportDone => (
+                None,
+                Some(TransientPopup {
+                    lines: vec!["Importing journals...".to_string()],
+                    expires_at: Instant::now() + Duration::from_millis(350),
+                }),
+            ),
+            StartupAction::PersistentError { title, lines } => (Some(Popup::Error { title, lines }), None),
+        };
+        Self {
+            config,
+            store,
+            entries,
+            selected,
+            state: UiState::Main,
+            popup,
+            filter: FilterState::default(),
+            sort: SortState { descending: true },
+            transient_popup,
+        }
+    }
+
+    fn run(
+        &mut self,
+        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
+    ) -> Result<()> {
+        loop {
+            if self
+                .transient_popup
+                .as_ref()
+                .is_some_and(|popup| Instant::now() >= popup.expires_at)
+            {
+                self.transient_popup = None;
+            }
+
+            terminal.draw(|frame| self.draw(frame))?;
+
+            if !event::poll(Duration::from_millis(50))? {
+                continue;
+            }
+
+            let Event::Key(key) = event::read()? else {
+                continue;
+            };
+
+            if let Some(popup) = self.popup.clone() {
+                if self.handle_popup(key, popup)? {
+                    return Ok(());
+                }
+                continue;
+            }
+
+            match &mut self.state {
+                UiState::Main => {
+                    if self.handle_main(key)? {
+                        return Ok(());
+                    }
+                }
+                UiState::Form(form) => self.handle_form(key, form)?,
+                UiState::Editor(editor) => {
+                    if self.handle_editor(key, editor)? {
+                        return Ok(());
+                    }
+                }
+                UiState::Filter(dialog) => self.handle_filter(key, dialog),
+                UiState::Sort(dialog) => self.handle_sort(key, dialog),
+                UiState::Help(dialog) => self.handle_help(key, dialog),
+            }
+        }
+    }
+
+    fn draw(&self, frame: &mut Frame) {
+        let chunks = Layout::default()
+            .direction(Direction::Vertical)
+            .constraints([Constraint::Min(1), Constraint::Length(2)])
+            .split(frame.area());
+        let body = Layout::default()
+            .direction(Direction::Horizontal)
+            .constraints([Constraint::Length(24), Constraint::Min(1)])
+            .split(chunks[0]);
+
+        self.draw_list(frame, body[0]);
+        self.draw_content(frame, body[1]);
+        self.draw_footer(frame, chunks[1]);
+
+        if let Some(popup) = &self.transient_popup {
+            self.draw_transient_popup(frame, popup);
+        }
+
+        match &self.state {
+            UiState::Form(form) => self.draw_form(frame, form),
+            UiState::Filter(dialog) => self.draw_filter(frame, dialog),
+            UiState::Sort(dialog) => self.draw_sort(frame, dialog),
+            UiState::Help(dialog) => self.draw_help(frame, dialog),
+            UiState::Main | UiState::Editor(_) => {}
+        }
+
+        if let Some(popup) = &self.popup {
+            self.draw_popup(frame, popup);
+        }
+    }
