mod app;
mod backend;
mod cli;
mod config;
mod theme;

use std::path::PathBuf;

use anyhow::{anyhow, Context, Result};
use clap::error::ErrorKind;

use app::{run_app, StartupAction};
use backend::{BackendStore, ImportedTransfer};
use cli::{build_cli, Commands, ThemeCommands};
use config::{load_effective_config, ConfigTarget};
use theme::{print_default_theme, resolve_theme_target, write_default_theme};

fn main() {
    if let Err(err) = real_main() {
        eprintln!("Error: {err}");
        std::process::exit(1);
    }
}

fn real_main() -> Result<()> {
    let bin_name = current_bin_name();
    let mut cmd = build_cli(&bin_name);
    let matches = match cmd.try_get_matches() {
        Ok(matches) => matches,
        Err(err) => match err.kind() {
            ErrorKind::DisplayHelp | ErrorKind::DisplayVersion => {
                print!("{err}");
                return Ok(());
            }
            _ => {
                err.print()?;
                std::process::exit(2);
            }
        },
    };

    if matches.get_flag("version") {
        println!("tui-journal 0.16.1");
        return Ok(());
    }

    let cli = cli::Cli::from_matches(&matches)?;
    match cli.command {
        Some(Commands::Theme { command }) => handle_theme(cli.config.as_deref(), command),
        Some(Commands::PrintConfig) => {
            let effective = load_effective_config(cli.config.as_deref(), &cli)?;
            print!("{}", effective.render());
            Ok(())
        }
        Some(Commands::AssignPriority { priority }) => {
            ensure_tty()?;
            let effective = load_effective_config(cli.config.as_deref(), &cli)?;
            let store = BackendStore::from_effective_config(&effective)?;
            store.assign_priority(priority)?;
            run_app(effective, StartupAction::AssignPriorityDone)
        }
        Some(Commands::ImportJournals { path }) => {
            ensure_tty()?;
            let effective = load_effective_config(cli.config.as_deref(), &cli)?;
            let action = match std::fs::read_to_string(&path) {
                Ok(raw) => match serde_json::from_str::<ImportedTransfer>(&raw) {
                    Ok(transfer) => {
                        let store = BackendStore::from_effective_config(&effective)?;
                        store.import_entries(&transfer.entries)?;
                        StartupAction::ImportDone
                    }
                    Err(err) => StartupAction::PersistentError {
                        title: "Error".to_string(),
                        lines: vec![
                            "Error while parsing import file.".to_string(),
                            format!("Error: {err}"),
                        ],
                    },
                },
                Err(_) => StartupAction::PersistentError {
                    title: "Error".to_string(),
                    lines: vec![format!("Import file doesn't exist: path {}", path.display())],
                },
            };
            run_app(effective, action)
        }
        None => {
            ensure_tty()?;
            let effective = load_effective_config(cli.config.as_deref(), &cli)?;
            run_app(effective, StartupAction::None)
        }
    }
}

fn handle_theme(config_path: Option<&PathBuf>, command: ThemeCommands) -> Result<()> {
    let target = resolve_theme_target(config_path)?;
    match command {
        ThemeCommands::PrintPath => {
            if target.ignored_non_dir {
                println!("INFO: Custom config directory is ignored in themese because it's not a directory.");
            }
            println!("{}", target.theme_path.display());
            Ok(())
        }
        ThemeCommands::PrintDefault => {
            print_default_theme();
            Ok(())
        }
        ThemeCommands::WriteDefaults => {
            if target.ignored_non_dir {
                println!("INFO: Custom config directory is ignored in themese because it's not a directory.");
            }
            write_default_theme(&target.theme_path)
        }
    }
}

fn current_bin_name() -> String {
    std::env::args_os()
        .next()
        .and_then(|arg| PathBuf::from(arg).file_name().map(|s| s.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "executable".to_string())
}

fn ensure_tty() -> Result<()> {
    std::fs::OpenOptions::new()
        .read(true)
        .write(true)
        .open("/dev/tty")
        .map(|_| ())
        .map_err(|err| anyhow!(err))
}

/workspace/src/app.rs.content:
use std::io::{self, Stdout};
use std::time::{Duration, Instant};

use anyhow::Result;
use crossterm::event::{self, Event, KeyCode, KeyEvent, KeyModifiers};
use crossterm::execute;
use crossterm::terminal::{
    disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen,
};
use ratatui::backend::CrosstermBackend;
use ratatui::layout::{Constraint, Direction, Layout, Rect};
use ratatui::style::{Modifier, Style};
use ratatui::text::{Line, Span, Text};
use ratatui::widgets::{Block, Borders, Clear, List, ListItem, Paragraph, Tabs, Wrap};
use ratatui::{Frame, Terminal};

use crate::backend::{parse_any_date, sort_entries, BackendStore, Entry};
use crate::config::{BackendType, EffectiveConfig};

#[derive(Debug, Clone)]
pub enum StartupAction {
    None,
    AssignPriorityDone,
    ImportDone,
    PersistentError { title: String, lines: Vec<String> },
}

pub fn run_app(config: EffectiveConfig, startup_action: StartupAction) -> Result<()> {
    let store = BackendStore::from_effective_config(&config)?;
    let mut entries = store.load_entries()?;
    let mut app = App::new(config, store, entries, startup_action);
    let mut terminal = setup_terminal()?;
    let result = app.run(&mut terminal);
    restore_terminal(&mut terminal)?;
    result
}

struct App {
    config: EffectiveConfig,
    store: BackendStore,
    entries: Vec<Entry>,
    selected: Option<usize>,
    state: UiState,
    popup: Option<Popup>,
    filter: FilterState,
    sort: SortState,
    transient_popup: Option<TransientPopup>,
}

#[derive(Debug, Clone)]
enum UiState {
    Main,
    Form(FormState),
    Editor(EditorState),
    Filter(FilterDialog),
    Sort(SortDialog),
    Help(HelpDialog),
}

#[derive(Debug, Clone)]
enum Popup {
    DeleteConfirm,
    SaveConfirm,
    Error { title: String, lines: Vec<String> },
}

#[derive(Debug, Clone)]
struct TransientPopup {
    lines: Vec<String>,
    expires_at: Instant,
}

#[derive(Debug, Clone)]
struct FormState {
    mode: FormMode,
    title: String,
    date: String,
    priority: String,
    tags: String,
    focus: FormField,
    error: Option<(FormField, String)>,
    entry_id: Option<u64>,
    content: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FormMode {
    Create,
    Edit,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FormField {
    Title,
    Date,
    Priority,
    Tags,
}

#[derive(Debug, Clone)]
struct EditorState {
    entry_id: u64,
    buffer: String,
    dirty: bool,
    mode: EditorMode,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum EditorMode {
    Insert,
    Normal,
}

#[derive(Debug, Clone, Default)]
struct FilterState {
    title: String,
    content: String,
    priority: String,
    selected_tags: Vec<String>,
    matching_logic_and: bool,
}

#[derive(Debug, Clone)]
struct FilterDialog {
    working: FilterState,
    focus: FilterField,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FilterField {
    Logic,
    Title,
    Content,
    Priority,
    Tags,
}

#[derive(Debug, Clone)]
struct SortState {
    descending: bool,
}

#[derive(Debug, Clone)]
struct SortDialog {
    descending: bool,
}

#[derive(Debug, Clone, Default)]
struct HelpDialog {
    tab: usize,
    scroll: usize,
}

impl App {
    fn new(
        config: EffectiveConfig,
        store: BackendStore,
        mut entries: Vec<Entry>,
        startup_action: StartupAction,
    ) -> Self {
        sort_entries(&mut entries);
        let selected = if entries.is_empty() { None } else { Some(0) };
        let (popup, transient_popup) = match startup_action {
            StartupAction::None => (None, None),
            StartupAction::AssignPriorityDone => (
                None,
                Some(TransientPopup {
                    lines: vec!["Assigning Priority to Journals...".to_string()],
                    expires_at: Instant::now() + Duration::from_millis(350),
                }),
            ),
            StartupAction::ImportDone => (
                None,
                Some(TransientPopup {
                    lines: vec!["Importing journals...".to_string()],
                    expires_at: Instant::now() + Duration::from_millis(350),
                }),
            ),
            StartupAction::PersistentError { title, lines } => (Some(Popup::Error { title, lines }), None),
        };
        Self {
            config,
            store,
            entries,
            selected,
            state: UiState::Main,
            popup,
            filter: FilterState::default(),
            sort: SortState { descending: true },
            transient_popup,
        }
    }

    fn run(
        &mut self,
        terminal: &mut Terminal<CrosstermBackend<Stdout>>,
    ) -> Result<()> {
        loop {
            if self
                .transient_popup
                .as_ref()
                .is_some_and(|popup| Instant::now() >= popup.expires_at)
            {
                self.transient_popup = None;
            }

            terminal.draw(|frame| self.draw(frame))?;

            if !event::poll(Duration::from_millis(50))? {
                continue;
            }

            let Event::Key(key) = event::read()? else {
                continue;
            };

            if let Some(popup) = self.popup.clone() {
                if self.handle_popup(key, popup)? {
                    return Ok(());
                }
                continue;
            }

            match &mut self.state {
                UiState::Main => {
                    if self.handle_main(key)? {
                        return Ok(());
                    }
                }
                UiState::Form(form) => self.handle_form(key, form)?,
                UiState::Editor(editor) => {
                    if self.handle_editor(key, editor)? {
                        return Ok(());
                    }
                }
                UiState::Filter(dialog) => self.handle_filter(key, dialog),
                UiState::Sort(dialog) => self.handle_sort(key, dialog),
                UiState::Help(dialog) => self.handle_help(key, dialog),
            }
        }
    }

    fn draw(&self, frame: &mut Frame) {
        let chunks = Layout::default()
            .direction(Direction::Vertical)
            .constraints([Constraint::Min(1), Constraint::Length(2)])
            .split(frame.area());
        let body = Layout::default()
            .direction(Direction::Horizontal)
            .constraints([Constraint::Length(24), Constraint::Min(1)])
            .split(chunks[0]);

        self.draw_list(frame, body[0]);
        self.draw_content(frame, body[1]);
        self.draw_footer(frame, chunks[1]);

        if let Some(popup) = &self.transient_popup {
            self.draw_transient_popup(frame, popup);
        }

        match &self.state {
            UiState::Form(form) => self.draw_form(frame, form),
            UiState::Filter(dialog) => self.draw_filter(frame, dialog),
            UiState::Sort(dialog) => self.draw_sort(frame, dialog),
            UiState::Help(dialog) => self.draw_help(frame, dialog),
            UiState::Main | UiState::Editor(_) => {}
        }

        if let Some(popup) = &self.popup {
            self.draw_popup(frame, popup);
        }
    }

    fn draw_list(&self, frame: &mut Frame, area: Rect) {
        let title = Block::default().borders(Borders::ALL).title("Journals");
        if self.entries.is_empty() {
            let text = Paragraph::new("Use 'n' to create new\nentry").block(title);
            frame.render_widget(text, area);
            return;
        }

        let items = self
            .filtered_entries()
            .iter()
            .enumerate()
            .map(|(idx, entry)| {
                let selected = self.selected == Some(idx);
                let mut lines = vec![
                    Line::from(if selected {
                        format!("> {}", truncate(&entry.title, 20))
                    } else {
                        format!("  {}", truncate(&entry.title, 20))
                    }),
                    Line::from(format!("  {}", format_list_date(entry.date))),
                ];
                if let Some(priority) = entry.priority {
                    lines.push(Line::from(format!("  Priority: {priority}")));
                }
                if !entry.tags.is_empty() {
                    lines.push(Line::from(format!("  {}", entry.tags.join(", "))));
                }
                ListItem::new(lines)
            })
            .collect::<Vec<_>>();

        let list = List::new(items).block(
            Block::default()
                .borders(Borders::ALL)
                .title(format!(
                    "Journals{}",
                    self.counter_suffix(self.filtered_entries().len())
                )),
        );
        frame.render_widget(list, area);
    }

    fn draw_content(&self, frame: &mut Frame, area: Rect) {
        let (title, text) = match &self.state {
            UiState::Editor(editor) => {
                let mut title = match editor.mode {
                    EditorMode::Insert => "Content - EDIT".to_string(),
                    EditorMode::Normal => "Content - NORMAL".to_string(),
                };
                if editor.dirty {
                    title.push_str(" *");
                }
                (title, editor.buffer.clone())
            }
            _ => {
                let content = self
                    .selected_entry()
                    .map(|entry| entry.content.clone())
                    .unwrap_or_default();
                ("Content".to_string(), content)
            }
        };
        let paragraph = Paragraph::new(text)
            .block(Block::default().borders(Borders::ALL).title(title))
            .wrap(Wrap { trim: false });
        frame.render_widget(paragraph, area);
    }

    fn draw_footer(&self, frame: &mut Frame, area: Rect) {
        let lines = match &self.state {
            UiState::Editor(editor) if editor.mode == EditorMode::Insert => vec![
                "Back to Editor Normal Mode: 'Esc','<Ctrl-c>','<Ctrl-[>' |  Edit using Emacs motions".to_string(),
                String::new(),
            ],
            UiState::Editor(editor) if editor.mode == EditorMode::Normal => vec![
                "Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Show help: '?'".to_string(),
                String::new(),
            ],
            _ => vec![
                "Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Open filter: 'f' | Open".to_string(),
                "sort options: 'o' | Show help: '?'".to_string(),
            ],
        };
        let paragraph = Paragraph::new(Text::from(lines));
        frame.render_widget(paragraph, area);
    }

    fn draw_transient_popup(&self, frame: &mut Frame, popup: &TransientPopup) {
        let width = popup
            .lines
            .iter()
            .map(|line| line.len())
            .max()
            .unwrap_or(0)
            .saturating_add(4) as u16;
        let height = popup.lines.len() as u16 + 2;
        let area = centered_rect(width, height, frame.area());
        let block = Block::default().borders(Borders::ALL);
        let text = Paragraph::new(popup.lines.join("\n")).block(block).alignment(ratatui::layout::Alignment::Center);
        frame.render_widget(Clear, area);
        frame.render_widget(text, area);
    }

    fn draw_popup(&self, frame: &mut Frame, popup: &Popup) {
        match popup {
            Popup::DeleteConfirm => {
                let area = centered_rect(44, 8, frame.area());
                let text = Paragraph::new(Text::from(vec![
                    Line::from(""),
                    Line::from("     Do you want to remove the current"),
                    Line::from("                 journal?"),
                    Line::from(""),
                    Line::from("               (Y)es , (N)o"),
                    Line::from(""),
                ]))
                .block(Block::default().borders(Borders::ALL));
                frame.render_widget(Clear, area);
                frame.render_widget(text, area);
            }
            Popup::SaveConfirm => {
                let area = centered_rect(44, 8, frame.area());
                let text = Paragraph::new(Text::from(vec![
                    Line::from(""),
                    Line::from("  Do you want to save the changes on the"),
                    Line::from("             current journal?"),
                    Line::from(""),
                    Line::from("          (Y)es , (N)o , (C)ancel"),
                    Line::from(""),
                ]))
                .block(Block::default().borders(Borders::ALL));
                frame.render_widget(Clear, area);
                frame.render_widget(text, area);
            }
            Popup::Error { title, lines } => {
                let rendered = if lines.len() == 1 {
                    vec![
                        Line::from(""),
                        Line::from(lines[0].clone()),
                        Line::from(""),
                        Line::from("                   (O)k                   "),
                        Line::from(""),
                    ]
                } else {
                    let mut out = vec![Line::from("")];
                    for line in lines {
                        out.push(Line::from(center_text(line, 42)));
                    }
                    out.push(Line::from("                   (O)k                   "));
                    out.push(Line::from(""));
                    out
                };
                let area = centered_rect(44, rendered.len() as u16 + 2, frame.area());
                let text = Paragraph::new(Text::from(rendered))
                    .block(Block::default().borders(Borders::ALL).title(title.as_str()));
                frame.render_widget(Clear, area);
                frame.render_widget(text, area);
            }
        }
    }

    fn draw_form(&self, frame: &mut Frame, form: &FormState) {
        let title = match form.mode {
            FormMode::Create => "Create journal",
            FormMode::Edit => "Edit journal",
        };
        let area = centered_rect(56, 19, frame.area());
        frame.render_widget(Clear, area);
        let block = Block::default().borders(Borders::ALL).title(title);
        frame.render_widget(block, area);

        let inner = Rect {
            x: area.x + 4,
            y: area.y + 2,
            width: area.width - 8,
            height: area.height - 4,
        };
        let rows = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Length(3),
                Constraint::Length(3),
                Constraint::Length(3),
                Constraint::Length(3),
                Constraint::Length(1),
                Constraint::Length(1),
                Constraint::Length(1),
            ])
            .split(inner);

        self.draw_form_field(frame, rows[0], "Title", &form.title, form.focus == FormField::Title, form.error.as_ref());
        self.draw_form_field(frame, rows[1], "Date", &form.date, form.focus == FormField::Date, form.error.as_ref());
        self.draw_form_field(
            frame,
            rows[2],
            "Priority",
            &form.priority,
            form.focus == FormField::Priority,
            form.error.as_ref(),
        );
        self.draw_form_field(frame, rows[3], "Tags", &form.tags, form.focus == FormField::Tags, form.error.as_ref());

        frame.render_widget(
            Paragraph::new("Enter or <Ctrl-m>: confirm | Esc or <Ctrl-c>:\nCancel | Tab: Change focused control |\n<Ctrl-Space> or <Ctrl-t>: Open tags")
                .wrap(Wrap { trim: false }),
            Rect {
                x: inner.x + 2,
                y: rows[4].y,
                width: inner.width - 2,
                height: 3,
            },
        );
    }

    fn draw_form_field(
        &self,
        frame: &mut Frame,
        area: Rect,
        label: &str,
        value: &str,
        active: bool,
        error: Option<&(FormField, String)>,
    ) {
        let field = match label {
            "Title" => FormField::Title,
            "Date" => FormField::Date,
            "Priority" => FormField::Priority,
            _ => FormField::Tags,
        };
        let title = if let Some((error_field, msg)) = error {
            if *error_field == field {
                format!("{label} : {msg}")
            } else {
                label.to_string()
            }
        } else {
            label.to_string()
        };
        let block = Block::default()
            .borders(Borders::ALL)
            .title(title)
            .style(if active { Style::default() } else { Style::default() });
        let text = Paragraph::new(value.to_string()).block(block);
        frame.render_widget(text, area);
    }

    fn draw_filter(&self, frame: &mut Frame, dialog: &FilterDialog) {
        let area = centered_rect(56, 20, frame.area());
        frame.render_widget(Clear, area);
        frame.render_widget(Block::default().borders(Borders::ALL).title("Filter"), area);
        let inner = Rect {
            x: area.x + 4,
            y: area.y + 2,
            width: area.width - 8,
            height: area.height - 4,
        };
        let rows = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Length(2),
                Constraint::Length(3),
                Constraint::Length(3),
                Constraint::Length(3),
                Constraint::Length(4),
                Constraint::Length(3),
            ])
            .split(inner);
        let logic_label = if dialog.working.matching_logic_and {
            "Matching Logic (AND)"
        } else {
            "Matching Logic (OR)"
        };
        frame.render_widget(
            Paragraph::new(logic_label).block(Block::default().borders(Borders::ALL)),
            rows[0],
        );
        self.draw_simple_field(frame, rows[1], "Title", &dialog.working.title, dialog.focus == FilterField::Title);
        self.draw_simple_field(
            frame,
            rows[2],
            "Content",
            &dialog.working.content,
            dialog.focus == FilterField::Content,
        );
        self.draw_simple_field(
            frame,
            rows[3],
            "Priority",
            &dialog.working.priority,
            dialog.focus == FilterField::Priority,
        );
        let available_tags = self.available_tags();
        let tags_text = if available_tags.is_empty() {
            "\n  No journals with tags provided".to_string()
        } else {
            available_tags
                .into_iter()
                .map(|tag| {
                    if dialog.working.selected_tags.contains(&tag) {
                        format!("[x] {tag}")
                    } else {
                        format!("[ ] {tag}")
                    }
                })
                .collect::<Vec<_>>()
                .join("\n")
        };
        frame.render_widget(
            Paragraph::new(tags_text).block(Block::default().borders(Borders::ALL).title("Tags")),
            rows[4],
        );
        frame.render_widget(
            Paragraph::new(
                "Tab: Change focused control | Enter or <Ctrl-m>:\nConfirm | Esc or <Ctrl-c>: Cancel | <Ctrl-r>:\nChange Matching Logic | <Space>: Tags Toggle Selected",
            )
            .wrap(Wrap { trim: false }),
            rows[5],
        );
    }

    fn draw_sort(&self, frame: &mut Frame, dialog: &SortDialog) {
        let area = centered_rect(56, 20, frame.area());
        frame.render_widget(Clear, area);
        frame.render_widget(Block::default().borders(Borders::ALL).title("Sort"), area);
        let inner = Rect {
            x: area.x + 4,
            y: area.y + 2,
            width: area.width - 8,
            height: area.height - 4,
        };
        let rows = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Length(3),
                Constraint::Length(4),
                Constraint::Length(4),
                Constraint::Length(4),
            ])
            .split(inner);
        frame.render_widget(
            Paragraph::new(format!(
                "Sort Order\n\n{}",
                if dialog.descending { "Descending" } else { "Ascending" }
            ))
            .block(Block::default().borders(Borders::ALL)),
            rows[0],
        );
        frame.render_widget(
            Paragraph::new(">> Title").block(Block::default().borders(Borders::ALL).title("Available Criteria")),
            rows[1],
        );
        frame.render_widget(
            Paragraph::new(">> Date\nPriority")
                .block(Block::default().borders(Borders::ALL).title("Applied Criteria")),
            rows[2],
        );
        frame.render_widget(
            Paragraph::new(
                "Tab: Change focused control | Enter or <Ctrl-m>:\nConfirm | Esc or <Ctrl-c>: Cancel |<o>: Change\nSort Order | <Space>: Move criteria to other\nlist |<j/k> or <up/down> cycle between criteria\n| <Ctrl-d> Load default",
            )
            .wrap(Wrap { trim: false }),
            rows[3],
        );
    }

    fn draw_help(&self, frame: &mut Frame, dialog: &HelpDialog) {
        let area = centered_rect(70, 20, frame.area());
        frame.render_widget(Clear, area);
        frame.render_widget(Block::default().borders(Borders::ALL).title("Help"), area);
        let inner = Rect {
            x: area.x + 2,
            y: area.y + 1,
            width: area.width - 4,
            height: area.height - 2,
        };
        let tabs = Tabs::new(vec!["Global", "Editor", "Multi-Select"])
            .block(Block::default().borders(Borders::ALL).title("Tabs"))
            .select(dialog.tab)
            .style(Style::default())
            .highlight_style(Style::default().add_modifier(Modifier::BOLD | Modifier::UNDERLINED));
        frame.render_widget(tabs, Rect { x: inner.x, y: inner.y, width: inner.width, height: 3 });

        let help_lines = match dialog.tab {
            0 => vec![
                "q           Exit               Exit the program",
                "?           Show help          Show keybindings overview",
                "<Ctrl-l>,   Cycle focus        Move focus to the next control",
                "Tab         forward",
                "<Ctrl-h>,   Cycle focus        Move focus to the previous",
                "BackTab     backward           control",
                "Down, j     Select next        Select next entry in the journals",
                "            journal            list",
                "Up, k       Select previous    Select previous entry in the",
                "            journal            journal list",
                "n           Create new         Opens dialog to add a new journal",
                "            journal            entry",
                "e           Edit current       Open entry dialog to edit current",
                "            journal            journal entry if any",
                "Delete, d,  Delete journal     Delete current journal entry",
                "<Ctrl-d>                        if any",
                "Enter,      Edit journal       Start editing current journal",
                "<Ctrl-m>    content            entry content in editor",
            ],
            1 => vec![
                "Esc,        Back to Editor     Exit editor special modes",
                "<Ctrl-c>,   Normal Mode        (insert, visual) and go back to",
                "<Ctrl-[>                        normal mode",
                "s, <Ctrl-s> Save               Save changes on journal",
                "                                content",
            ],
            _ => vec!["Multi-select help is not available in this reimplementation."],
        };

        let paragraph = Paragraph::new(help_lines.join("\n"))
            .block(Block::default().borders(Borders::ALL).title("Global Keybindings"))
            .wrap(Wrap { trim: false });
