    fn draw_simple_field(&self, frame: &mut Frame, area: Rect, title: &str, value: &str, _active: bool) {
        frame.render_widget(
            Paragraph::new(value.to_string()).block(Block::default().borders(Borders::ALL).title(title)),
            area,
        );
    }

    fn handle_popup(&mut self, key: KeyEvent, popup: Popup) -> Result<bool> {
        match popup {
            Popup::DeleteConfirm => match key.code {
                KeyCode::Char('y') | KeyCode::Char('Y') => {
                    if let Some(entry) = self.selected_entry().cloned() {
                        self.store.delete_entry(entry.id)?;
                        self.reload_entries()?;
                    }
                    self.popup = None;
                }
                KeyCode::Char('n') | KeyCode::Char('N') | KeyCode::Esc => self.popup = None,
                _ => {}
            },
            Popup::SaveConfirm => match key.code {
                KeyCode::Char('y') | KeyCode::Char('Y') => {
                    if let UiState::Editor(editor) = &self.state {
                        self.store.update_entry_content(editor.entry_id, &editor.buffer)?;
                    }
                    return Ok(true);
                }
                KeyCode::Char('n') | KeyCode::Char('N') => return Ok(true),
                KeyCode::Char('c') | KeyCode::Char('C') | KeyCode::Esc => self.popup = None,
                _ => {}
            },
            Popup::Error { .. } => {
                if matches!(key.code, KeyCode::Enter) {
                    self.popup = None;
                }
            }
        }
        Ok(false)
    }

    fn handle_main(&mut self, key: KeyEvent) -> Result<bool> {
        match key.code {
            KeyCode::Char('q') => return Ok(true),
            KeyCode::Down | KeyCode::Char('j') => self.move_selection(1),
            KeyCode::Up | KeyCode::Char('k') => self.move_selection(-1),
            KeyCode::Char('n') => self.state = UiState::Form(FormState::create()),
            KeyCode::Char('e') => {
                if let Some(entry) = self.selected_entry().cloned() {
                    self.state = UiState::Form(FormState::edit(entry));
                }
            }
            KeyCode::Char('d') => {
                if self.selected.is_some() {
                    self.popup = Some(Popup::DeleteConfirm);
                }
            }
            KeyCode::Enter => {
                if let Some(entry) = self.selected_entry().cloned() {
                    self.state = UiState::Editor(EditorState {
                        entry_id: entry.id,
                        buffer: entry.content,
                        dirty: false,
                        mode: EditorMode::Insert,
                    });
                }
            }
            KeyCode::Char('f') => {
                self.state = UiState::Filter(FilterDialog {
                    working: self.filter.clone(),
                    focus: FilterField::Title,
                });
            }
            KeyCode::Char('o') => {
                self.state = UiState::Sort(SortDialog {
                    descending: self.sort.descending,
                });
            }
            KeyCode::Char('?') => self.state = UiState::Help(HelpDialog::default()),
            _ => {}
        }
        Ok(false)
    }

    fn handle_form(&mut self, key: KeyEvent, form: &mut FormState) -> Result<()> {
        match key.code {
            KeyCode::Esc => {
                self.state = UiState::Main;
                return Ok(());
            }
            KeyCode::Tab => {
                form.focus = match form.focus {
                    FormField::Title => FormField::Date,
                    FormField::Date => FormField::Priority,
                    FormField::Priority => FormField::Tags,
                    FormField::Tags => FormField::Title,
                };
            }
            KeyCode::Backspace => {
                let target = form.active_field_mut();
                target.pop();
                form.error = None;
            }
            KeyCode::Enter => {
                match validate_form(form) {
                    Ok((title, date, priority, tags)) => {
                        match form.mode {
                            FormMode::Create => {
                                self.store.create_entry(title, date, priority, tags)?;
                            }
                            FormMode::Edit => {
                                if let Some(id) = form.entry_id {
                                    let entry = Entry {
                                        id,
                                        title,
                                        date,
                                        priority,
                                        tags,
                                        content: form.content.clone(),
                                    };
                                    self.store.update_entry_metadata(&entry)?;
                                }
                            }
                        }
                        self.reload_entries()?;
                        self.state = UiState::Main;
                    }
                    Err((field, message)) => {
                        form.error = Some((field, message));
                    }
                }
            }
            KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.state = UiState::Main;
            }
            KeyCode::Char(ch) => {
                form.active_field_mut().push(ch);
                form.error = None;
                if form.focus == FormField::Date && !is_date_input_valid(&form.date) {
                    form.error = Some((FormField::Date, "input contains invalid characters".to_string()));
                }
                if form.focus == FormField::Priority && !form.priority.chars().all(|c| c.is_ascii_digit()) {
                    form.error = Some((FormField::Priority, "input contains invalid characters".to_string()));
                }
            }
            _ => {}
        }
        Ok(())
    }

    fn handle_editor(&mut self, key: KeyEvent, editor: &mut EditorState) -> Result<bool> {
        match editor.mode {
            EditorMode::Insert => match (key.code, key.modifiers) {
                (KeyCode::Esc, _) | (KeyCode::Char('c'), modifiers) if modifiers.contains(KeyModifiers::CONTROL) => {
                    editor.mode = EditorMode::Normal;
                }
                (KeyCode::Char('s'), modifiers) if modifiers.contains(KeyModifiers::CONTROL) => {
                    self.store.update_entry_content(editor.entry_id, &editor.buffer)?;
                    editor.dirty = false;
                    self.reload_entries()?;
                }
                (KeyCode::Backspace, _) => {
                    editor.buffer.pop();
                    editor.dirty = true;
                }
                (KeyCode::Enter, _) => {
                    editor.buffer.push('\n');
                    editor.dirty = true;
                }
                (KeyCode::Char(ch), _) => {
                    editor.buffer.push(ch);
                    editor.dirty = true;
                }
                _ => {}
            },
            EditorMode::Normal => match key.code {
                KeyCode::Char('q') => {
                    if editor.dirty {
                        self.popup = Some(Popup::SaveConfirm);
                        return Ok(false);
                    }
                    return Ok(true);
                }
                KeyCode::Enter => {
                    editor.mode = EditorMode::Insert;
                }
                KeyCode::Char('?') => self.state = UiState::Help(HelpDialog { tab: 1, scroll: 0 }),
                KeyCode::Char('s') => {
                    self.store.update_entry_content(editor.entry_id, &editor.buffer)?;
                    editor.dirty = false;
                    self.reload_entries()?;
                }
                _ => {}
            },
        }
        Ok(false)
    }

    fn handle_filter(&mut self, key: KeyEvent, dialog: &mut FilterDialog) {
        match key.code {
            KeyCode::Esc => self.state = UiState::Main,
            KeyCode::Tab => {
                dialog.focus = match dialog.focus {
                    FilterField::Logic => FilterField::Title,
                    FilterField::Title => FilterField::Content,
                    FilterField::Content => FilterField::Priority,
                    FilterField::Priority => FilterField::Tags,
                    FilterField::Tags => FilterField::Logic,
                };
            }
            KeyCode::Enter => {
                self.filter = dialog.working.clone();
                self.reload_filtered_selection();
                self.state = UiState::Main;
            }
            KeyCode::Char('r') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                dialog.working.matching_logic_and = !dialog.working.matching_logic_and;
            }
            KeyCode::Backspace => match dialog.focus {
                FilterField::Title => {
                    dialog.working.title.pop();
                }
                FilterField::Content => {
                    dialog.working.content.pop();
                }
                FilterField::Priority => {
                    dialog.working.priority.pop();
                }
                FilterField::Logic | FilterField::Tags => {}
            },
            KeyCode::Char(' ') if dialog.focus == FilterField::Tags => {
                if let Some(tag) = self.available_tags().into_iter().next() {
                    if let Some(position) = dialog.working.selected_tags.iter().position(|item| item == &tag) {
                        dialog.working.selected_tags.remove(position);
                    } else {
                        dialog.working.selected_tags.push(tag);
                    }
                }
            }
            KeyCode::Char(ch) => match dialog.focus {
                FilterField::Title => dialog.working.title.push(ch),
                FilterField::Content => dialog.working.content.push(ch),
                FilterField::Priority => dialog.working.priority.push(ch),
                FilterField::Logic | FilterField::Tags => {}
            },
            _ => {}
        }
    }

    fn handle_sort(&mut self, key: KeyEvent, dialog: &mut SortDialog) {
        match key.code {
            KeyCode::Esc => self.state = UiState::Main,
            KeyCode::Enter => {
                self.sort.descending = dialog.descending;
                self.reload_entries_only();
                self.state = UiState::Main;
            }
            KeyCode::Char('o') => dialog.descending = !dialog.descending,
            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                dialog.descending = true;
            }
            _ => {}
        }
    }

    fn handle_help(&mut self, key: KeyEvent, dialog: &mut HelpDialog) {
        match key.code {
            KeyCode::Esc | KeyCode::Char('?') => self.state = UiState::Main,
            KeyCode::Tab | KeyCode::Char('l') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                dialog.tab = (dialog.tab + 1) % 3;
            }
            KeyCode::BackTab | KeyCode::Char('h') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                dialog.tab = (dialog.tab + 2) % 3;
            }
            _ => {}
        }
    }

    fn move_selection(&mut self, delta: isize) {
        let len = self.filtered_entries().len();
        if len == 0 {
            self.selected = None;
            return;
        }
        let current = self.selected.unwrap_or(0) as isize;
        let next = (current + delta).clamp(0, len as isize - 1) as usize;
        self.selected = Some(next);
    }

    fn reload_entries(&mut self) -> Result<()> {
        self.entries = self.store.load_entries()?;
        self.reload_entries_only();
        Ok(())
    }

    fn reload_entries_only(&mut self) {
        sort_entries(&mut self.entries);
        if !self.sort.descending {
            self.entries.reverse();
        }
        self.reload_filtered_selection();
    }

    fn reload_filtered_selection(&mut self) {
        let len = self.filtered_entries().len();
        self.selected = match len {
            0 => None,
            _ => Some(self.selected.unwrap_or(0).min(len - 1)),
        };
    }

    fn filtered_entries(&self) -> Vec<Entry> {
        let mut entries = self.entries.clone();
        entries.retain(|entry| self.filter.matches(entry));
        entries
    }

    fn selected_entry(&self) -> Option<&Entry> {
        let filtered = self.filtered_entries();
        self.selected
            .and_then(|index| filtered.get(index).cloned())
            .and_then(|selected| self.entries.iter().find(|entry| entry.id == selected.id))
    }

    fn available_tags(&self) -> Vec<String> {
        let mut tags = self
            .entries
            .iter()
            .flat_map(|entry| entry.tags.iter().cloned())
            .collect::<Vec<_>>();
        tags.sort();
        tags.dedup();
        tags
    }

    fn counter_suffix(&self, len: usize) -> String {
        match len {
            0 => String::new(),
            _ => format!("{}{}", "─".repeat(19usize.saturating_sub(len.to_string().len() * 2)), format!("{}/{}", self.selected.unwrap_or(0) + 1, len)),
        }
    }
}

impl FormState {
    fn create() -> Self {
        Self {
            mode: FormMode::Create,
            title: String::new(),
            date: chrono::Utc::now().date_naive().format("%d-%m-%Y").to_string(),
            priority: String::new(),
            tags: String::new(),
            focus: FormField::Title,
            error: None,
            entry_id: None,
            content: String::new(),
        }
    }

    fn edit(entry: Entry) -> Self {
        Self {
            mode: FormMode::Edit,
            title: entry.title,
            date: entry.date.format("%d-%m-%Y").to_string(),
            priority: entry.priority.map(|value| value.to_string()).unwrap_or_default(),
            tags: entry.tags.join(","),
            focus: FormField::Title,
            error: None,
            entry_id: Some(entry.id),
            content: entry.content,
        }
    }

    fn active_field_mut(&mut self) -> &mut String {
        match self.focus {
            FormField::Title => &mut self.title,
            FormField::Date => &mut self.date,
            FormField::Priority => &mut self.priority,
            FormField::Tags => &mut self.tags,
        }
    }
}

impl FilterState {
    fn matches(&self, entry: &Entry) -> bool {
        let mut checks = Vec::new();
        if !self.title.is_empty() {
            checks.push(entry.title.to_lowercase().contains(&self.title.to_lowercase()));
        }
        if !self.content.is_empty() {
            checks.push(entry.content.to_lowercase().contains(&self.content.to_lowercase()));
        }
        if !self.priority.is_empty() {
            checks.push(entry.priority.map(|value| value.to_string()) == Some(self.priority.clone()));
        }
        if !self.selected_tags.is_empty() {
            checks.push(self.selected_tags.iter().all(|tag| entry.tags.contains(tag)));
        }
        if checks.is_empty() {
            true
        } else if self.matching_logic_and {
            checks.into_iter().all(|value| value)
        } else {
            checks.into_iter().any(|value| value)
        }
    }
}

fn validate_form(form: &FormState) -> std::result::Result<(String, chrono::NaiveDate, Option<u16>, Vec<String>), (FormField, String)> {
    if form.title.is_empty() {
        return Err((FormField::Title, "Title can't be empty".to_string()));
    }
    let date = parse_any_date(&form.date).map_err(|_| {
        (
            FormField::Date,
            "input contains invalid characters".to_string(),
        )
    })?;
    let priority = if form.priority.is_empty() {
        None
    } else {
        Some(form.priority.parse::<u16>().map_err(|_| {
            (
                FormField::Priority,
                "input contains invalid characters".to_string(),
            )
        })?)
    };
    let tags = form
        .tags
        .split(',')
        .filter_map(|tag| {
            let trimmed = tag.trim();
            if trimmed.is_empty() {
                None
            } else {
                Some(trimmed.to_string())
            }
        })
        .collect::<Vec<_>>();
    Ok((form.title.clone(), date, priority, tags))
}

fn is_date_input_valid(value: &str) -> bool {
    value.chars().all(|ch| ch.is_ascii_digit() || ch == '-') && value.len() <= 10
}

fn format_list_date(date: chrono::NaiveDate) -> String {
    format!("{},{},{}", date.day(), date.month(), date.year())
}

fn truncate(value: &str, max: usize) -> String {
    value.chars().take(max).collect()
}

fn center_text(value: &str, width: usize) -> String {
    let len = value.len();
    if len >= width {
        value.to_string()
    } else {
        let left = (width - len) / 2;
        let right = width - len - left;
        format!("{}{}{}", " ".repeat(left), value, " ".repeat(right))
    }
}

fn centered_rect(width: u16, height: u16, area: Rect) -> Rect {
    Rect {
        x: area.x + area.width.saturating_sub(width) / 2,
        y: area.y + area.height.saturating_sub(height) / 2,
        width: width.min(area.width),
        height: height.min(area.height),
    }
}

fn setup_terminal() -> Result<Terminal<CrosstermBackend<Stdout>>> {
    enable_raw_mode()?;
    let mut stdout = io::stdout();
    execute!(stdout, EnterAlternateScreen)?;
    let backend = CrosstermBackend::new(stdout);
    let terminal = Terminal::new(backend)?;
    Ok(terminal)
}

fn restore_terminal(terminal: &mut Terminal<CrosstermBackend<Stdout>>) -> Result<()> {
    disable_raw_mode()?;
    execute!(terminal.backend_mut(), LeaveAlternateScreen)?;
    terminal.show_cursor()?;
    Ok(())
}

