use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{anyhow, Context, Result};
use chrono::{DateTime, NaiveDate, Utc};
use rusqlite::{params, Connection};
use serde::{Deserialize, Serialize};

use crate::config::{BackendType, EffectiveConfig};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    pub id: u64,
    pub date: NaiveDate,
    pub title: String,
    pub content: String,
    pub tags: Vec<String>,
    pub priority: Option<u16>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ImportedTransfer {
    pub version: u16,
    pub entries: Vec<ImportedEntry>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ImportedEntry {
    pub id: u64,
    #[serde(with = "json_date")]
    pub date: NaiveDate,
    pub title: String,
    pub content: String,
    #[serde(default)]
    pub tags: Vec<String>,
    pub priority: Option<u16>,
}

#[derive(Debug, Clone)]
pub enum BackendStore {
    Json(JsonStore),
    Sqlite(SqliteStore),
}

impl BackendStore {
    pub fn from_effective_config(config: &EffectiveConfig) -> Result<Self> {
        match config.backend_type {
            BackendType::Json => Ok(Self::Json(JsonStore {
                path: config.json_backend_file_path.clone(),
            })),
            BackendType::Sqlite => Ok(Self::Sqlite(SqliteStore::new(
                config.sqlite_backend_file_path.clone(),
            )?)),
        }
    }

    pub fn load_entries(&self) -> Result<Vec<Entry>> {
        match self {
            BackendStore::Json(store) => store.load_entries(),
            BackendStore::Sqlite(store) => store.load_entries(),
        }
    }

    pub fn create_entry(
        &self,
        title: String,
        date: NaiveDate,
        priority: Option<u16>,
        tags: Vec<String>,
    ) -> Result<Entry> {
        match self {
            BackendStore::Json(store) => store.create_entry(title, date, priority, tags),
            BackendStore::Sqlite(store) => store.create_entry(title, date, priority, tags),
        }
    }

    pub fn update_entry_metadata(&self, entry: &Entry) -> Result<()> {
        match self {
            BackendStore::Json(store) => store.update_entry(entry),
            BackendStore::Sqlite(store) => store.update_entry(entry),
        }
    }

    pub fn update_entry_content(&self, id: u64, content: &str) -> Result<()> {
        match self {
            BackendStore::Json(store) => store.update_content(id, content),
            BackendStore::Sqlite(store) => store.update_content(id, content),
        }
    }

    pub fn delete_entry(&self, id: u64) -> Result<()> {
        match self {
            BackendStore::Json(store) => store.delete_entry(id),
            BackendStore::Sqlite(store) => store.delete_entry(id),
        }
    }

    pub fn assign_priority(&self, priority: u16) -> Result<()> {
        match self {
            BackendStore::Json(store) => store.assign_priority(priority),
            BackendStore::Sqlite(store) => store.assign_priority(priority),
        }
    }

    pub fn import_entries(&self, entries: &[ImportedEntry]) -> Result<()> {
        match self {
            BackendStore::Json(store) => store.import_entries(entries),
            BackendStore::Sqlite(store) => store.import_entries(entries),
        }
    }
}

#[derive(Debug, Clone)]
pub struct JsonStore {
    path: PathBuf,
}

impl JsonStore {
    fn load_entries(&self) -> Result<Vec<Entry>> {
        if !self.path.exists() {
            return Ok(Vec::new());
        }
        let raw = fs::read_to_string(&self.path)?;
        let stored: Vec<JsonEntry> = serde_json::from_str(&raw)?;
        Ok(stored.into_iter().map(Entry::from).collect())
    }

    fn save_entries(&self, entries: &[Entry]) -> Result<()> {
        let json: Vec<JsonEntry> = entries.iter().cloned().map(JsonEntry::from).collect();
        let raw = serde_json::to_string(&json)?;
        fs::write(&self.path, raw)?;
        Ok(())
    }

    fn create_entry(
        &self,
        title: String,
        date: NaiveDate,
        priority: Option<u16>,
        tags: Vec<String>,
    ) -> Result<Entry> {
        let mut entries = self.load_entries()?;
        let id = entries.iter().map(|entry| entry.id).max().map_or(0, |id| id + 1);
        let entry = Entry {
            id,
            date,
            title,
            content: String::new(),
            tags,
            priority,
        };
        entries.push(entry.clone());
        self.save_entries(&entries)?;
        Ok(entry)
    }

    fn update_entry(&self, updated: &Entry) -> Result<()> {
        let mut entries = self.load_entries()?;
        if let Some(entry) = entries.iter_mut().find(|entry| entry.id == updated.id) {
            *entry = updated.clone();
            self.save_entries(&entries)?;
        }
        Ok(())
    }

    fn update_content(&self, id: u64, content: &str) -> Result<()> {
        let mut entries = self.load_entries()?;
        if let Some(entry) = entries.iter_mut().find(|entry| entry.id == id) {
            entry.content = content.to_string();
            self.save_entries(&entries)?;
        }
        Ok(())
    }

    fn delete_entry(&self, id: u64) -> Result<()> {
        let mut entries = self.load_entries()?;
        entries.retain(|entry| entry.id != id);
        self.save_entries(&entries)
    }

    fn assign_priority(&self, priority: u16) -> Result<()> {
        let mut entries = self.load_entries()?;
        for entry in &mut entries {
            if entry.priority.is_none() {
                entry.priority = Some(priority);
            }
        }
        self.save_entries(&entries)
    }

    fn import_entries(&self, imported: &[ImportedEntry]) -> Result<()> {
        let mut entries = self.load_entries()?;
        let mut next_id = entries.iter().map(|entry| entry.id).max().map_or(0, |id| id + 1);
        for imported_entry in imported {
            entries.push(Entry {
                id: next_id,
                date: imported_entry.date,
                title: imported_entry.title.clone(),
                content: imported_entry.content.clone(),
                tags: imported_entry.tags.clone(),
                priority: imported_entry.priority,
            });
            next_id += 1;
        }
        self.save_entries(&entries)
    }
}

