                ],
            )?;
            let id = conn.last_insert_rowid() as u64;
            self.replace_tags(&conn, id, &entry.tags)?;
        }
        Ok(())
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct JsonEntry {
    id: u64,
    #[serde(with = "json_date")]
    date: NaiveDate,
    title: String,
    content: String,
    #[serde(default)]
    tags: Vec<String>,
    priority: Option<u16>,
}

impl From<JsonEntry> for Entry {
    fn from(value: JsonEntry) -> Self {
        Entry {
            id: value.id,
            date: value.date,
            title: value.title,
            content: value.content,
            tags: value.tags,
            priority: value.priority,
        }
    }
}

impl From<Entry> for JsonEntry {
    fn from(value: Entry) -> Self {
        JsonEntry {
            id: value.id,
            date: value.date,
            title: value.title,
            content: value.content,
            tags: value.tags,
            priority: value.priority,
        }
    }
}

pub fn sort_entries(entries: &mut [Entry]) {
    entries.sort_by(|left, right| {
        right
            .date
            .cmp(&left.date)
            .then_with(|| right.priority.cmp(&left.priority))
            .then_with(|| left.id.cmp(&right.id))
    });
}

pub fn parse_any_date(value: &str) -> Result<NaiveDate> {
    DateTime::parse_from_rfc3339(value)
        .map(|dt| dt.naive_utc().date())
        .or_else(|_| NaiveDate::parse_from_str(value, "%d-%m-%Y"))
        .map_err(|err| anyhow!(err))
}

fn sqlite_date_string(date: NaiveDate) -> String {
    format!("{}T00:00:00+00:00", date.format("%Y-%m-%d"))
}

mod json_date {
    use anyhow::{anyhow, Result};
    use chrono::{DateTime, NaiveDate};
    use serde::{Deserialize, Deserializer, Serializer};

    pub fn serialize<S>(value: &NaiveDate, serializer: S) -> std::result::Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(&format!("{}T00:00:00Z", value.format("%Y-%m-%d")))
    }

    pub fn deserialize<'de, D>(deserializer: D) -> std::result::Result<NaiveDate, D::Error>
    where
        D: Deserializer<'de>,
    {
        let raw = String::deserialize(deserializer)?;
        DateTime::parse_from_rfc3339(&raw)
            .map(|dt| dt.naive_utc().date())
            .map_err(serde::de::Error::custom)
    }
}

