+			}
+		}
+		cli.Command = Command{Kind: cmdAssignPriority, Priority: uint16(value)}
+		return cli, nil
+	case "theme":
+		if len(args) == 1 || (len(args) > 1 && (args[1] == "-h" || args[1] == "--help" || args[1] == "help")) {
+			return cli, &cliResponse{Message: themeHelp(bin)}
