+package main
+
+import (
+	"encoding/json"
+	"fmt"
+	"os"
+	"sort"
+	"strings"
+	"time"
+)
+
+type Entry struct {
+	ID       uint64   `json:"id"`
+	Date     DateOnly `json:"date"`
+	Title    string   `json:"title"`
+	Content  string   `json:"content"`
+	Tags     []string `json:"tags"`
+	Priority *uint16  `json:"priority"`
+}
+
+type ImportedTransfer struct {
+	Version uint16 `json:"version"`
+	Entries []Entry `json:"entries"`
+}
+
+type DateOnly struct {
+	time.Time
+}
+
+func (d DateOnly) MarshalJSON() ([]byte, error) {
+	return json.Marshal(d.Format("2006-01-02T00:00:00Z"))
+}
+
+func (d *DateOnly) UnmarshalJSON(data []byte) error {
+	var s string
+	if err := json.Unmarshal(data, &s); err != nil {
+		return err
+	}
+	t, err := time.Parse(time.RFC3339, s)
+	if err != nil {
+		return err
+	}
+	d.Time = t.UTC()
+	return nil
+}
+
+func ParseDateOnly(s string) (DateOnly, error) {
+	if strings.Contains(s, "T") {
+		t, err := time.Parse(time.RFC3339, s)
+		if err != nil {
+			return DateOnly{}, err
+		}
+		return DateOnly{Time: t.UTC()}, nil
+	}
+	t, err := time.Parse("02-01-2006", s)
+	if err != nil {
+		return DateOnly{}, err
+	}
+	return DateOnly{Time: time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, time.UTC)}, nil
+}
+
+func TodayDateOnly() DateOnly {
+	now := time.Now().UTC()
+	return DateOnly{Time: time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)}
+}
+
+func (d DateOnly) FormDate() string {
+	return d.Format("02-01-2006")
+}
+
+func (d DateOnly) ListDate() string {
+	return fmt.Sprintf("%d,%d,%d", d.Day(), int(d.Month()), d.Year())
+}
+
+type Store interface {
+	LoadEntries() ([]Entry, error)
+	CreateEntry(title string, date DateOnly, priority *uint16, tags []string) (Entry, error)
+	UpdateEntry(entry Entry) error
+	UpdateEntryContent(id uint64, content string) error
+	DeleteEntry(id uint64) error
+	AssignPriority(value uint16) error
+	ImportEntries(entries []Entry) error
+}
+
+func NewStore(cfg Config) (Store, error) {
+	if cfg.BackendType == BackendJSON {
+		return &JSONStore{Path: cfg.JSONBackendFilePath}, nil
+	}
+	return NewSQLiteStore(cfg.SQLiteBackendFilePath)
+}
+
+type JSONStore struct {
+	Path string
+}
+
+func (s *JSONStore) LoadEntries() ([]Entry, error) {
+	raw, err := os.ReadFile(s.Path)
+	if err != nil {
+		if os.IsNotExist(err) {
+			return nil, nil
+		}
+		return nil, err
+	}
+	if len(raw) == 0 {
+		return nil, nil
+	}
+	var entries []Entry
+	if err := json.Unmarshal(raw, &entries); err != nil {
+		return nil, err
+	}
+	return entries, nil
+}
+
+func (s *JSONStore) save(entries []Entry) error {
+	raw, err := json.Marshal(entries)
+	if err != nil {
+		return err
+	}
+	return os.WriteFile(s.Path, raw, 0644)
+}
+
+func (s *JSONStore) CreateEntry(title string, date DateOnly, priority *uint16, tags []string) (Entry, error) {
+	entries, err := s.LoadEntries()
+	if err != nil {
+		return Entry{}, err
+	}
+	var next uint64
+	for _, entry := range entries {
+		if entry.ID >= next {
