+func execSQL(db *C.sqlite3, sql string) error {
+	csql := C.CString(sql)
+	defer C.free(unsafe.Pointer(csql))
+	var errmsg *C.char
+	rc := C.sqlite3_exec(db, csql, nil, nil, &errmsg)
+	if rc != sqliteOK {
+		if errmsg != nil {
+			defer C.sqlite3_free(unsafe.Pointer(errmsg))
+			return fmt.Errorf("%s", C.GoString(errmsg))
+		}
+		return fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db)))
+	}
+	return nil
+}
+
+func queryRows(db *C.sqlite3, sql string) ([][]string, error) {
+	csql := C.CString(sql)
+	defer C.free(unsafe.Pointer(csql))
+	var stmt *C.sqlite3_stmt
+	rc := C.sqlite3_prepare_v2(db, csql, -1, &stmt, nil)
+	if rc != sqliteOK {
+		return nil, fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db)))
+	}
+	defer C.sqlite3_finalize(stmt)
+	var rows [][]string
+	for {
+		rc = C.sqlite3_step(stmt)
+		if rc == sqliteDone {
+			break
+		}
+		if rc != sqliteRow {
+			return nil, fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db)))
+		}
+		row := make([]string, 0, 5)
+		for i := 0; ; i++ {
+			ctype := C.sqlite3_column_type(stmt, C.int(i))
+			if i > 0 && ctype == 0 && C.sqlite3_column_text(stmt, C.int(i)) == nil {
+				break
+			}
+			if i > 10 {
+				break
+			}
+			if ctype == sqliteNull {
+				row = append(row, "")
+				continue
+			}
+			text := C.sqlite3_column_text(stmt, C.int(i))
+			if text == nil {
+				break
+			}
+			row = append(row, C.GoString((*C.char)(unsafe.Pointer(text))))
+		}
+		rows = append(rows, row)
+	}
+	return rows, nil
+}
