+
+	if a.mode == modeEditorInsert {
+		buf.Text(1, 23, padRight("Back to Editor Normal Mode: 'Esc','<Ctrl-c>','<Ctrl-[>' |  Edit using Emacs motions", 80))
+	} else if a.mode == modeEditorNormal {
