+func (a *uiApp) handleKey(k Key) (bool, error) {
+	if a.popup.Kind != "" {
+		return a.handlePopupKey(k)
+	}
+	switch a.mode {
+	case modeMain:
+		return a.handleMainKey(k)
+	case modeForm:
+		return false, a.handleFormKey(k)
+	case modeEditorInsert:
+		return false, a.handleEditorInsertKey(k)
+	case modeEditorNormal:
+		return a.handleEditorNormalKey(k)
+	case modeFilter:
+		a.handleFilterKey(k)
+	case modeSort:
+		a.handleSortKey(k)
+	case modeHelp:
+		a.handleHelpKey(k)
+	}
+	return false, nil
+}
+
+func (a *uiApp) handlePopupKey(k Key) (bool, error) {
+	switch a.popup.Kind {
+	case "delete":
+		if k.Char == 'y' || k.Char == 'Y' {
+			visible := a.filteredEntries()
+			if len(visible) > 0 {
+				if err := a.store.DeleteEntry(visible[a.selected].ID); err != nil {
+					return false, err
+				}
+				if err := a.reload(); err != nil {
+					return false, err
+				}
+			}
+			a.popup = popupState{}
+		} else if k.Char == 'n' || k.Char == 'N' || k.Name == "esc" {
+			a.popup = popupState{}
+		}
+	case "save":
+		if k.Char == 'y' || k.Char == 'Y' {
+			e := a.editor()
+			if err := a.store.UpdateEntryContent(e.EntryID, e.Buffer); err != nil {
+				return false, err
+			}
+			return true, nil
+		}
+		if k.Char == 'n' || k.Char == 'N' {
+			return true, nil
+		}
+		if k.Char == 'c' || k.Char == 'C' || k.Name == "esc" {
+			a.popup = popupState{}
+		}
+	case "error":
+		if k.Name == "enter" {
+			a.popup = popupState{}
+		}
+	}
+	return false, nil
+}
+
+func (a *uiApp) handleMainKey(k Key) (bool, error) {
+	switch {
+	case k.Char == 'q':
+		return true, nil
+	case k.Name == "down" || k.Char == 'j':
+		a.moveSelection(1)
+	case k.Name == "up" || k.Char == 'k':
+		a.moveSelection(-1)
+	case k.Char == 'n':
+		a.mode = modeForm
+		a.formState = &formState{Mode: "create", Date: TodayDateOnly().FormDate()}
+	case k.Char == 'e':
+		visible := a.filteredEntries()
+		if len(visible) > 0 {
+			entry := visible[a.selected]
+			a.mode = modeForm
+			a.formState = &formState{
+				Mode:     "edit",
+				EntryID:  entry.ID,
+				Title:    entry.Title,
+				Date:     entry.Date.FormDate(),
+				Priority: priorityString(entry.Priority),
+				Tags:     strings.Join(entry.Tags, ","),
+				Content:  entry.Content,
+			}
+		}
+	case k.Char == 'd':
+		if len(a.filteredEntries()) > 0 {
+			a.popup = popupState{Kind: "delete"}
+		}
+	case k.Name == "enter":
+		visible := a.filteredEntries()
+		if len(visible) > 0 {
+			entry := visible[a.selected]
+			a.mode = modeEditorInsert
+			a.editorState = &editorState{EntryID: entry.ID, Buffer: entry.Content}
+		}
+	case k.Char == 'f':
+		a.mode = modeFilter
+		a.filterState = &filterState{Title: a.filter.Title, Content: a.filter.Content, Priority: a.filter.Priority, Tags: append([]string(nil), a.filter.Tags...), And: a.filter.And}
+	case k.Char == 'o':
+		a.mode = modeSort
+		a.sortState = &sortState{Descending: a.sortDescending}
+	case k.Char == '?':
+		a.mode = modeHelp
+		a.helpState = &helpState{}
+	}
+	return false, nil
+}
+
+func (a *uiApp) handleFormKey(k Key) error {
+	f := a.form()
+	switch {
+	case k.Name == "esc" || k.Name == "ctrl-c":
+		a.mode = modeMain
+	case k.Name == "tab":
+		f.Focus = (f.Focus + 1) % 4
+	case k.Name == "backspace":
+		field := a.formFieldPtr(f)
+		if len(*field) > 0 {
+			*field = (*field)[:len(*field)-1]
+		}
+		f.ErrField, f.ErrMsg = "", ""
+	case k.Name == "enter":
+		if strings.TrimSpace(f.Title) == "" {
+			f.ErrField, f.ErrMsg = "title", "Title can't be empty"
+			return nil
+		}
+		date, err := ParseDateOnly(f.Date)
+		if err != nil || !isDateInputValid(f.Date) {
+			f.ErrField, f.ErrMsg = "date", "input contains invalid characters"
+			return nil
+		}
+		var priority *uint16
+		if strings.TrimSpace(f.Priority) != "" {
+			n, err := strconv.ParseUint(f.Priority, 10, 16)
+			if err != nil {
+				f.ErrField, f.ErrMsg = "priority", "input contains invalid characters"
+				return nil
+			}
+			v := uint16(n)
+			priority = &v
+		}
+		tags := parseTags(f.Tags)
+		switch f.Mode {
+		case "create":
+			if _, err := a.store.CreateEntry(f.Title, date, priority, tags); err != nil {
+				return err
+			}
+		case "edit":
+			entry := Entry{
+				ID:       f.EntryID,
+				Title:    f.Title,
+				Date:     date,
+				Content:  f.Content,
+				Tags:     tags,
+				Priority: priority,
+			}
+			if err := a.store.UpdateEntry(entry); err != nil {
+				return err
+			}
+		}
+		if err := a.reload(); err != nil {
+			return err
+		}
+		a.mode = modeMain
+	default:
+		if k.Char != 0 {
+			field := a.formFieldPtr(f)
+			*field += string(k.Char)
+			f.ErrField, f.ErrMsg = "", ""
+			if f.Focus == 1 && !isDateInputValid(f.Date) {
+				f.ErrField, f.ErrMsg = "date", "input contains invalid characters"
+			}
+			if f.Focus == 2 && !isDigits(f.Priority) {
+				f.ErrField, f.ErrMsg = "priority", "input contains invalid characters"
+			}
+		}
+	}
+	return nil
+}
+
+func (a *uiApp) handleEditorInsertKey(k Key) error {
+	e := a.editor()
+	switch {
+	case k.Name == "esc" || k.Name == "ctrl-c":
+		a.mode = modeEditorNormal
+	case k.Name == "ctrl-s":
+		if err := a.store.UpdateEntryContent(e.EntryID, e.Buffer); err != nil {
+			return err
+		}
+		e.Dirty = false
+		return a.reload()
+	case k.Name == "backspace":
+		if len(e.Buffer) > 0 {
+			e.Buffer = e.Buffer[:len(e.Buffer)-1]
+			e.Dirty = true
+		}
+	case k.Name == "enter":
+		e.Buffer += "\n"
+		e.Dirty = true
+	default:
+		if k.Char != 0 {
+			e.Buffer += string(k.Char)
+			e.Dirty = true
+		}
+	}
+	return nil
+}
+
+func (a *uiApp) handleEditorNormalKey(k Key) (bool, error) {
+	e := a.editor()
+	switch {
+	case k.Char == 'q':
+		if e.Dirty {
+			a.popup = popupState{Kind: "save"}
+			return false, nil
+		}
+		return true, nil
+	case k.Name == "enter":
+		a.mode = modeEditorInsert
+	case k.Char == '?':
+		a.mode = modeHelp
+		a.helpState = &helpState{Tab: 1}
+	case k.Char == 's':
+		if err := a.store.UpdateEntryContent(e.EntryID, e.Buffer); err != nil {
+			return false, err
+		}
+		e.Dirty = false
+		if err := a.reload(); err != nil {
+			return false, err
+		}
+	}
+	return false, nil
+}
+
+func (a *uiApp) handleFilterKey(k Key) {
+	f := a.filterDialog()
+	switch {
+	case k.Name == "esc" || k.Name == "ctrl-c":
+		a.mode = modeMain
+	case k.Name == "tab":
+		f.Focus = (f.Focus + 1) % 5
+	case k.Name == "enter":
+		a.filter = FilterState{Title: f.Title, Content: f.Content, Priority: f.Priority, Tags: append([]string(nil), f.Tags...), And: f.And}
+		a.adjustSelection()
+		a.mode = modeMain
+	case k.Name == "ctrl-r":
+		f.And = !f.And
+	case k.Name == "backspace":
+		switch f.Focus {
+		case 1:
+			if len(f.Title) > 0 {
+				f.Title = f.Title[:len(f.Title)-1]
+			}
+		case 2:
+			if len(f.Content) > 0 {
+				f.Content = f.Content[:len(f.Content)-1]
+			}
+		case 3:
+			if len(f.Priority) > 0 {
+				f.Priority = f.Priority[:len(f.Priority)-1]
+			}
+		}
+	case k.Name == "space":
+		if f.Focus == 4 {
+			tags := a.availableTags()
+			if len(tags) > 0 {
+				tag := tags[0]
+				if containsString(f.Tags, tag) {
+					f.Tags = removeString(f.Tags, tag)
+				} else {
+					f.Tags = append(f.Tags, tag)
+				}
+			}
+		}
+	default:
+		if k.Char != 0 {
+			switch f.Focus {
+			case 1:
+				f.Title += string(k.Char)
+			case 2:
+				f.Content += string(k.Char)
+			case 3:
+				f.Priority += string(k.Char)
+			}
+		}
+	}
+}
