+func (a *uiApp) adjustSelection() {
+	visible := a.filteredEntries()
+	if len(visible) == 0 {
+		a.selected = 0
+		return
+	}
+	if a.selected >= len(visible) {
+		a.selected = len(visible) - 1
+	}
+}
