+func (a *uiApp) moveSelection(delta int) {
+	visible := a.filteredEntries()
+	if len(visible) == 0 {
+		a.selected = 0
+		return
+	}
+	a.selected += delta
+	if a.selected < 0 {
+		a.selected = 0
+	}
+	if a.selected >= len(visible) {
+		a.selected = len(visible) - 1
+	}
+}
