+func normalizeCommand(arg string) string {
+	switch arg {
+	case "pc":
+		return "print-config"
+	case "imj":
+		return "import-journals"
+	case "ap":
+		return "assign-priority"
+	case "style":
+		return "theme"
+	default:
+		return arg
+	}
+}
