+func NewStore(cfg Config) (Store, error) {
+	if cfg.BackendType == BackendJSON {
+		return &JSONStore{Path: cfg.JSONBackendFilePath}, nil
+	}
+	return NewSQLiteStore(cfg.SQLiteBackendFilePath)
+}
+
+func (s *JSONStore) LoadEntries() ([]Entry, error) {
+	raw, err := os.ReadFile(s.Path)
+	if err != nil {
+		if os.IsNotExist(err) {
+			return nil, nil
+		}
+		return nil, err
+	}
+	if len(raw) == 0 {
+		return nil, nil
+	}
+	var entries []Entry
+	if err := json.Unmarshal(raw, &entries); err != nil {
+		return nil, err
+	}
+	return entries, nil
+}
+
+func (s *JSONStore) save(entries []Entry) error {
+	raw, err := json.Marshal(entries)
+	if err != nil {
+		return err
+	}
+	return os.WriteFile(s.Path, raw, 0644)
+}
+
+func (s *JSONStore) CreateEntry(title string, date DateOnly, priority *uint16, tags []string) (Entry, error) {
+	entries, err := s.LoadEntries()
+	if err != nil {
+		return Entry{}, err
+	}
+	var next uint64
+	for _, entry := range entries {
+		if entry.ID >= next {
+			next = entry.ID + 1
+		}
+	}
+	entry := Entry{ID: next, Date: date, Title: title, Content: "", Tags: tags, Priority: priority}
+	entries = append(entries, entry)
+	return entry, s.save(entries)
+}
+
+func (s *JSONStore) UpdateEntry(entry Entry) error {
+	entries, err := s.LoadEntries()
+	if err != nil {
+		return err
+	}
+	for i := range entries {
+		if entries[i].ID == entry.ID {
+			entries[i] = entry
+			break
+		}
+	}
+	return s.save(entries)
+}
+
+func (s *JSONStore) UpdateEntryContent(id uint64, content string) error {
+	entries, err := s.LoadEntries()
+	if err != nil {
+		return err
+	}
+	for i := range entries {
+		if entries[i].ID == id {
+			entries[i].Content = content
+			break
+		}
+	}
+	return s.save(entries)
+}
+
+func (s *JSONStore) DeleteEntry(id uint64) error {
+	entries, err := s.LoadEntries()
+	if err != nil {
+		return err
+	}
+	out := make([]Entry, 0, len(entries))
+	for _, entry := range entries {
+		if entry.ID != id {
+			out = append(out, entry)
+		}
+	}
+	return s.save(out)
+}
+
+func (s *JSONStore) AssignPriority(v uint16) error {
+	entries, err := s.LoadEntries()
+	if err != nil {
+		return err
+	}
+	for i := range entries {
+		if entries[i].Priority == nil {
+			value := v
+			entries[i].Priority = &value
+		}
+	}
+	return s.save(entries)
+}
+
+func (s *JSONStore) ImportEntries(entries []Entry) error {
+	current, err := s.LoadEntries()
+	if err != nil {
+		return err
+	}
+	var next uint64
+	for _, entry := range current {
+		if entry.ID >= next {
+			next = entry.ID + 1
+		}
+	}
+	for _, entry := range entries {
+		entry.ID = next
+		next++
+		current = append(current, entry)
+	}
+	return s.save(current)
+}
+
+func NewSQLiteStore(path string) (*SQLiteStore, error) {
+	s := &SQLiteStore{Path: path}
+	if err := s.initialize(); err != nil {
+		return nil, err
+	}
+	return s, nil
+}
+
+func (s *SQLiteStore) open() (*C.sqlite3, error) {
+	cpath := C.CString(s.Path)
+	defer C.free(unsafe.Pointer(cpath))
+	var db *C.sqlite3
+	if rc := C.sqlite3_open(cpath, &db); rc != sqliteOK {
+		if db != nil {
+			defer C.sqlite3_close(db)
+			return nil, fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db)))
+		}
+		return nil, fmt.Errorf("sqlite open error")
+	}
+	if err := execSQL(db, "PRAGMA foreign_keys = ON;"); err != nil {
+		C.sqlite3_close(db)
+		return nil, err
+	}
+	return db, nil
+}
+
+func (s *SQLiteStore) initialize() error {
+	db, err := s.open()
+	if err != nil {
+		return err
+	}
+	defer C.sqlite3_close(db)
+
+	schema := `
+CREATE TABLE IF NOT EXISTS _sqlx_migrations (
+    version BIGINT PRIMARY KEY,
+    description TEXT NOT NULL,
+    installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
+    success BOOLEAN NOT NULL,
+    checksum BLOB NOT NULL,
+    execution_time BIGINT NOT NULL
+);
+CREATE TABLE IF NOT EXISTS entries
+(
+  id        INTEGER PRIMARY KEY  NOT NULL,
+  title     TEXT                 NOT NULL,
+  date      DATE                 NOT NULL,
+  content   TEXT
+, priority INTEGER DEFAULT NULL);
+CREATE TABLE IF NOT EXISTS tags (
+  entry_id INTEGER NOT NULL,
+  tag TEXT NOT NULL,
+  PRIMARY KEY (entry_id, tag),
+  FOREIGN KEY (entry_id) REFERENCES entries (id) ON DELETE CASCADE
+);
+`
+	if err := execSQL(db, schema); err != nil {
+		return err
+	}
+	migrations := []string{
+		"INSERT OR IGNORE INTO _sqlx_migrations (version, description, success, checksum, execution_time) VALUES (20230509041613, 'init entries', 1, X'a9b962e074e56db0fbfbcf4874ed6d1e8d94313c9c0122247465cc26057ad3635235b208703db8a0843a8bc16cd50685', 217287);",
+		"INSERT OR IGNORE INTO _sqlx_migrations (version, description, success, checksum, execution_time) VALUES (20230613041405, 'add tags', 1, X'e0eb5fd4d092c82cb2bd4528ce27fe9c037f045245ac9f1235ee2cef07c75443e8fec98c3a5f0562c641b1bc5301f319', 267302);",
