+func (s *SQLiteStore) LoadEntries() ([]Entry, error) {
+	db, err := s.open()
+	if err != nil {
+		return nil, err
+	}
+	defer C.sqlite3_close(db)
+
+	rows, err := queryRows(db, "SELECT id, title, date, COALESCE(content, ''), COALESCE(priority, -1) FROM entries ORDER BY id ASC;", 5)
+	if err != nil {
+		return nil, err
+	}
+	entries := make([]Entry, 0, len(rows))
+	for _, row := range rows {
+		date, err := parseDateOnly(row[2])
+		if err != nil {
+			return nil, err
+		}
+		entry := Entry{
+			ID:      parseUint64(row[0]),
+			Title:   row[1],
+			Date:    date,
+			Content: row[3],
+		}
+		if row[4] != "-1" {
+			value := uint16(parseInt64(row[4]))
+			entry.Priority = &value
+		}
+		tagRows, err := queryRows(db, fmt.Sprintf("SELECT tag FROM tags WHERE entry_id = %d ORDER BY tag COLLATE NOCASE ASC;", entry.ID), 1)
+		if err != nil {
+			return nil, err
+		}
+		for _, tag := range tagRows {
+			entry.Tags = append(entry.Tags, tag[0])
+		}
+		entries = append(entries, entry)
+	}
+	return entries, nil
+}
+
+func (s *SQLiteStore) CreateEntry(title string, date DateOnly, priority *uint16, tags []string) (Entry, error) {
+	db, err := s.open()
+	if err != nil {
+		return Entry{}, err
+	}
+	defer C.sqlite3_close(db)
+	prioritySQL := "NULL"
+	if priority != nil {
+		prioritySQL = fmt.Sprintf("%d", *priority)
+	}
+	if err := execSQL(db, fmt.Sprintf("INSERT INTO entries (title, date, content, priority) VALUES ('%s', '%s', '', %s);", sqlQuote(title), date.SQLiteString(), prioritySQL)); err != nil {
+		return Entry{}, err
+	}
+	id := uint64(C.sqlite3_last_insert_rowid(db))
+	if err := replaceTags(db, id, tags); err != nil {
+		return Entry{}, err
+	}
+	return Entry{ID: id, Title: title, Date: date, Content: "", Tags: tags, Priority: priority}, nil
+}
+
+func (s *SQLiteStore) UpdateEntry(entry Entry) error {
+	db, err := s.open()
+	if err != nil {
+		return err
+	}
+	defer C.sqlite3_close(db)
+	prioritySQL := "NULL"
+	if entry.Priority != nil {
+		prioritySQL = fmt.Sprintf("%d", *entry.Priority)
+	}
+	if err := execSQL(db, fmt.Sprintf("UPDATE entries SET title = '%s', date = '%s', content = '%s', priority = %s WHERE id = %d;", sqlQuote(entry.Title), entry.Date.SQLiteString(), sqlQuote(entry.Content), prioritySQL, entry.ID)); err != nil {
+		return err
+	}
+	return replaceTags(db, entry.ID, entry.Tags)
+}
+
+func (s *SQLiteStore) UpdateEntryContent(id uint64, content string) error {
+	db, err := s.open()
+	if err != nil {
+		return err
+	}
+	defer C.sqlite3_close(db)
+	return execSQL(db, fmt.Sprintf("UPDATE entries SET content = '%s' WHERE id = %d;", sqlQuote(content), id))
+}
+
+func (s *SQLiteStore) DeleteEntry(id uint64) error {
+	db, err := s.open()
+	if err != nil {
+		return err
+	}
+	defer C.sqlite3_close(db)
+	return execSQL(db, fmt.Sprintf("DELETE FROM entries WHERE id = %d;", id))
+}
+
+func (s *SQLiteStore) AssignPriority(v uint16) error {
+	db, err := s.open()
+	if err != nil {
+		return err
+	}
+	defer C.sqlite3_close(db)
+	return execSQL(db, fmt.Sprintf("UPDATE entries SET priority = %d WHERE priority IS NULL;", v))
+}
+
+func (s *SQLiteStore) ImportEntries(entries []Entry) error {
+	db, err := s.open()
+	if err != nil {
+		return err
+	}
+	defer C.sqlite3_close(db)
+	for _, entry := range entries {
+		prioritySQL := "NULL"
+		if entry.Priority != nil {
+			prioritySQL = fmt.Sprintf("%d", *entry.Priority)
+		}
+		if err := execSQL(db, fmt.Sprintf("INSERT INTO entries (title, date, content, priority) VALUES ('%s', '%s', '%s', %s);", sqlQuote(entry.Title), entry.Date.SQLiteString(), sqlQuote(entry.Content), prioritySQL)); err != nil {
+			return err
+		}
+		id := uint64(C.sqlite3_last_insert_rowid(db))
+		if err := replaceTags(db, id, entry.Tags); err != nil {
+			return err
+		}
+	}
+	return nil
+}
+
+func replaceTags(db *C.sqlite3, entryID uint64, tags []string) error {
+	if err := execSQL(db, fmt.Sprintf("DELETE FROM tags WHERE entry_id = %d;", entryID)); err != nil {
+		return err
+	}
+	for _, tag := range tags {
+		if err := execSQL(db, fmt.Sprintf("INSERT INTO tags (entry_id, tag) VALUES (%d, '%s');", entryID, sqlQuote(tag))); err != nil {
+			return err
+		}
+	}
+	return nil
+}
+
+func execSQL(db *C.sqlite3, sql string) error {
+	csql := C.CString(sql)
+	defer C.free(unsafe.Pointer(csql))
+	var errmsg *C.char
+	rc := C.sqlite3_exec(db, csql, nil, nil, &errmsg)
+	if rc != sqliteOK {
+		if errmsg != nil {
+			defer C.sqlite3_free(unsafe.Pointer(errmsg))
+			return fmt.Errorf("%s", C.GoString(errmsg))
+		}
+		return fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db)))
+	}
+	return nil
+}
+
+func queryRows(db *C.sqlite3, sql string, cols int) ([][]string, error) {
+	csql := C.CString(sql)
+	defer C.free(unsafe.Pointer(csql))
+	var stmt *C.sqlite3_stmt
+	if rc := C.sqlite3_prepare_v2(db, csql, -1, &stmt, nil); rc != sqliteOK {
+		return nil, fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db)))
+	}
+	defer C.sqlite3_finalize(stmt)
+
+	var rows [][]string
+	for {
+		rc := C.sqlite3_step(stmt)
+		if rc == sqliteDone {
+			break
+		}
+		if rc != sqliteRow {
+			return nil, fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db)))
+		}
+		row := make([]string, cols)
+		for i := 0; i < cols; i++ {
+			text := C.sqlite3_column_text(stmt, C.int(i))
+			if text != nil {
+				row[i] = C.GoString((*C.char)(unsafe.Pointer(text)))
+			}
+		}
+		rows = append(rows, row)
+	}
+	return rows, nil
+}
+
+func sqlQuote(value string) string {
+	return strings.ReplaceAll(value, "'", "''")
+}
+
+func sortEntries(entries []Entry, descending bool) []Entry {
+	out := append([]Entry(nil), entries...)
+	sort.SliceStable(out, func(i, j int) bool {
+		left, right := out[i], out[j]
+		if descending {
+			if !left.Date.Equal(right.Date.Time) {
+				return left.Date.After(right.Date.Time)
+			}
+			lp, rp := -1, -1
+			if left.Priority != nil {
+				lp = int(*left.Priority)
+			}
+			if right.Priority != nil {
+				rp = int(*right.Priority)
+			}
+			if lp != rp {
+				return lp > rp
+			}
+			return left.ID < right.ID
+		}
+		if !left.Date.Equal(right.Date.Time) {
+			return left.Date.Before(right.Date.Time)
+		}
+		lp, rp := -1, -1
+		if left.Priority != nil {
+			lp = int(*left.Priority)
+		}
+		if right.Priority != nil {
+			rp = int(*right.Priority)
+		}
+		if lp != rp {
+			return lp < rp
+		}
+		return left.ID < right.ID
+	})
+	return out
+}
