+func RunUI(tty *os.File, cfg Config, action StartupAction) error {
+	restore, err := enableRawTTY()
+	if err != nil {
+		return err
+	}
+	defer restore()
+
+	fmt.Fprint(tty, "\x1b[?1049h\x1b[?25l")
+	defer fmt.Fprint(tty, "\x1b[?1049l\x1b[?25h")
+
+	store, err := NewStore(cfg)
+	if err != nil {
+		return err
+	}
+	entries, err := store.LoadEntries()
+	if err != nil {
+		return err
+	}
+
+	app := &UIApp{
+		store:          store,
+		entries:        entries,
+		sortDescending: true,
+	}
+	switch action.Kind {
+	case "assign":
+		app.transientLines = []string{"Assigning Priority to Journals..."}
+		app.transientUntil = time.Now().Add(350 * time.Millisecond)
+	case "import":
+		app.transientLines = []string{"Importing journals..."}
+		app.transientUntil = time.Now().Add(350 * time.Millisecond)
+	case "error":
+		app.popup = popupState{Kind: "error", Title: action.Title, Lines: action.Lines}
+	}
+	if len(app.visibleEntries()) == 0 {
+		app.selected = 0
+	}
+	return app.loop(tty)
+}
+
+func enableRawTTY() (func(), error) {
+	cmd := exec.Command("stty", "-F", "/dev/tty", "raw", "-echo", "min", "0", "time", "1")
+	if out, err := cmd.CombinedOutput(); err != nil {
+		return nil, fmt.Errorf("%v: %s", err, string(out))
+	}
+	return func() {
+		_ = exec.Command("stty", "-F", "/dev/tty", "sane").Run()
+	}, nil
+}
+
+func (a *UIApp) loop(tty *os.File) error {
+	for {
+		if !a.transientUntil.IsZero() && time.Now().After(a.transientUntil) {
+			a.transientUntil = time.Time{}
+			a.transientLines = nil
+		}
+		if err := a.draw(tty); err != nil {
+			return err
+		}
+		key, ok, err := a.readKey(tty)
+		if err != nil {
+			return err
+		}
+		if !ok {
+			continue
+		}
+		exit, err := a.handleKey(key)
+		if err != nil {
+			return err
+		}
+		if exit {
+			return nil
+		}
+	}
+}
+
+func (a *UIApp) draw(w io.Writer) error {
+	screen := NewScreen(80, 24)
+	a.drawMain(screen)
+	if !a.transientUntil.IsZero() && len(a.transientLines) > 0 {
+		drawPopupBox(screen, 23, 11, 35, 3, "", a.transientLines)
+	}
+	switch a.mode {
+	case modeForm:
+		a.drawForm(screen)
+	case modeFilter:
+		a.drawFilter(screen)
+	case modeSort:
+		a.drawSort(screen)
+	case modeHelp:
+		a.drawHelp(screen)
+	}
+	if a.popup.Kind != "" {
+		a.drawPopup(screen)
+	}
+	_, err := fmt.Fprintf(w, "\x1b[H%s", screen.String())
+	return err
+}
