+func (a *UIApp) drawMain(s *Screen) {
+	s.Box(1, 1, 24, 22, "Journals")
+	visible := a.visibleEntries()
+	if len(visible) > 0 {
+		count := fmt.Sprintf("%d/%d", a.selected+1, len(visible))
+		s.Text(24-len(count)-1, 22, count)
+	}
+
+	contentTitle := "Content"
+	if a.mode == modeEditorInsert {
+		contentTitle = "Content - EDIT"
+		if a.editor != nil && a.editor.Dirty {
+			contentTitle += " *"
+		}
+	} else if a.mode == modeEditorNormal {
+		contentTitle = "Content - NORMAL"
+		if a.editor != nil && a.editor.Dirty {
+			contentTitle += " *"
+		}
+	}
+	s.Box(24, 1, 57, 22, contentTitle)
+
+	if len(visible) == 0 {
+		s.Text(3, 3, "Use 'n' to create new")
+		s.Text(10, 4, "entry")
+	} else {
+		y := 2
+		for i, entry := range visible {
+			prefix := "  "
+			if i == a.selected {
+				prefix = "> "
+			}
+			s.Text(2, y, padRight(prefix+truncate(entry.Title, 20), 22))
+			y++
+			s.Text(2, y, padRight("  "+entry.Date.ListDate(), 22))
+			y++
+			if entry.Priority != nil {
+				s.Text(2, y, padRight(fmt.Sprintf("  Priority: %d", *entry.Priority), 22))
+				y++
+			}
+			if len(entry.Tags) > 0 {
+				s.Text(2, y, padRight("  "+strings.Join(entry.Tags, ", "), 22))
+				y++
+			}
+			if y > 21 {
+				break
+			}
+		}
+	}
+
+	content := ""
+	if a.mode == modeEditorInsert || a.mode == modeEditorNormal {
+		content = a.editor.Buffer
+	} else if len(visible) > 0 {
+		content = visible[a.selected].Content
+	}
+	lines := strings.Split(content, "\n")
+	for i, line := range lines {
+		if i >= 20 {
+			break
+		}
+		s.Text(26, 2+i, truncate(line, 54))
+	}
+
+	if a.mode == modeEditorInsert {
+		s.Text(1, 23, padRight("Back to Editor Normal Mode: 'Esc','<Ctrl-c>','<Ctrl-[>' |  Edit using Emacs motions", 80))
+	} else if a.mode == modeEditorNormal {
+		s.Text(1, 24, padRight("Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Show help: '?'", 80))
+	} else {
+		s.Text(1, 23, padRight("Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Open filter: 'f' | Open", 80))
+		s.Text(1, 24, padRight("sort options: 'o' | Show help: '?'", 80))
+	}
+}
