+func (a *UIApp) handleFormKey(k Key) error {
+	switch {
+	case k.Name == "esc" || k.Name == "ctrl-c":
+		a.mode = modeMain
+	case k.Name == "tab":
+		a.form.Focus = (a.form.Focus + 1) % 4
+	case k.Name == "backspace":
+		field := a.activeFormField()
+		if len(*field) > 0 {
+			*field = (*field)[:len(*field)-1]
+		}
+		a.form.ErrField, a.form.ErrMsg = "", ""
+	case k.Name == "enter":
+		if strings.TrimSpace(a.form.Title) == "" {
+			a.form.ErrField, a.form.ErrMsg = "title", "Title can't be empty"
+			return nil
+		}
+		date, err := parseDateOnly(a.form.Date)
+		if err != nil || !isDateInputValid(a.form.Date) {
+			a.form.ErrField, a.form.ErrMsg = "date", "input contains invalid characters"
+			return nil
+		}
+		var priority *uint16
+		if strings.TrimSpace(a.form.Priority) != "" {
+			n, err := strconv.ParseUint(a.form.Priority, 10, 16)
+			if err != nil {
+				a.form.ErrField, a.form.ErrMsg = "priority", "input contains invalid characters"
+				return nil
+			}
+			value := uint16(n)
+			priority = &value
+		}
+		tags := parseTags(a.form.Tags)
+		if a.form.Mode == "create" {
+			if _, err := a.store.CreateEntry(a.form.Title, date, priority, tags); err != nil {
+				return err
+			}
+		} else {
+			entry := Entry{
+				ID:       a.form.EntryID,
+				Title:    a.form.Title,
+				Date:     date,
+				Content:  a.form.Content,
+				Tags:     tags,
+				Priority: priority,
+			}
+			if err := a.store.UpdateEntry(entry); err != nil {
+				return err
+			}
+		}
+		if err := a.reload(); err != nil {
+			return err
+		}
+		a.mode = modeMain
+	case k.Char != 0:
+		field := a.activeFormField()
+		*field += string(k.Char)
+		a.form.ErrField, a.form.ErrMsg = "", ""
+		if a.form.Focus == 1 && !isDateInputValid(a.form.Date) {
