+func (a *UIApp) adjustSelection() {
+	visible := a.visibleEntries()
+	if len(visible) == 0 {
+		a.selected = 0
+		return
+	}
+	if a.selected >= len(visible) {
+		a.selected = len(visible) - 1
+	}
+	if a.selected < 0 {
+		a.selected = 0
+	}
+}
