+func (a *UIApp) moveSelection(delta int) {
+	visible := a.visibleEntries()
+	if len(visible) == 0 {
+		a.selected = 0
+		return
+	}
+	a.selected += delta
+	if a.selected < 0 {
+		a.selected = 0
+	}
+	if a.selected >= len(visible) {
+		a.selected = len(visible) - 1
+	}
