+func (a *UIApp) visibleEntries() []Entry {
+	entries := sortEntries(a.entries, a.sortDescending)
+	out := make([]Entry, 0, len(entries))
+	for _, entry := range entries {
+		if a.filterMatch(entry) {
+			out = append(out, entry)
+		}
+	}
+	return out
+}
+
+func (a *UIApp) filterMatch(entry Entry) bool {
+	checks := []bool{}
+	if a.filter.Title != "" {
+		checks = append(checks, strings.Contains(strings.ToLower(entry.Title), strings.ToLower(a.filter.Title)))
+	}
+	if a.filter.Content != "" {
+		checks = append(checks, strings.Contains(strings.ToLower(entry.Content), strings.ToLower(a.filter.Content)))
+	}
+	if a.filter.Priority != "" {
+		checks = append(checks, priorityString(entry.Priority) == a.filter.Priority)
+	}
+	if len(a.filter.Tags) > 0 {
+		matches := true
+		for _, tag := range a.filter.Tags {
+			if !containsString(entry.Tags, tag) {
+				matches = false
+				break
+			}
+		}
+		checks = append(checks, matches)
+	}
+	if len(checks) == 0 {
+		return true
+	}
+	if a.filter.And {
+		for _, check := range checks {
+			if !check {
+				return false
+			}
+		}
+		return true
+	}
+	for _, check := range checks {
+		if check {
+			return true
+		}
+	}
+	return false
+}
+
+func (a *UIApp) availableTags() []string {
+	set := map[string]bool{}
+	for _, entry := range a.entries {
+		for _, tag := range entry.Tags {
+			set[tag] = true
+		}
+	}
+	out := make([]string, 0, len(set))
+	for tag := range set {
+		out = append(out, tag)
+	}
+	sort.Slice(out, func(i, j int) bool {
+		return strings.ToLower(out[i]) < strings.ToLower(out[j])
+	})
+	return out
+}
+
+func (a *UIApp) readKey(tty *os.File) (Key, bool, error) {
+	buf := make([]byte, 16)
+	n, err := tty.Read(buf)
+	if err != nil && err != io.EOF {
+		return Key{}, false, err
+	}
+	if n > 0 {
+		a.rx = append(a.rx, buf[:n]...)
+	}
+	if len(a.rx) == 0 {
+		return Key{}, false, nil
+	}
+	key, used, ok := parseKeyBytes(a.rx)
+	if !ok {
+		return Key{}, false, nil
+	}
+	a.rx = a.rx[used:]
+	return key, true, nil
+}
+
+func parseKeyBytes(data []byte) (Key, int, bool) {
+	if len(data) == 0 {
+		return Key{}, 0, false
+	}
+	switch data[0] {
+	case 0:
+		return Key{Name: "ctrl-space"}, 1, true
+	case 3:
+		return Key{Name: "ctrl-c"}, 1, true
+	case 4:
+		return Key{Name: "ctrl-d"}, 1, true
+	case 8:
+		return Key{Name: "ctrl-h"}, 1, true
+	case 9:
+		return Key{Name: "tab"}, 1, true
+	case 10, 13:
+		return Key{Name: "enter"}, 1, true
+	case 12:
+		return Key{Name: "ctrl-l"}, 1, true
+	case 18:
+		return Key{Name: "ctrl-r"}, 1, true
+	case 19:
+		return Key{Name: "ctrl-s"}, 1, true
+	case 27:
+		if len(data) >= 3 && data[1] == '[' {
+			switch data[2] {
+			case 'A':
+				return Key{Name: "up"}, 3, true
+			case 'B':
+				return Key{Name: "down"}, 3, true
+			case 'Z':
+				return Key{Name: "backtab"}, 3, true
+			}
+		}
+		return Key{Name: "esc"}, 1, true
+	case 127:
+		return Key{Name: "backspace"}, 1, true
+	default:
+		if data[0] == ' ' {
+			return Key{Name: "space"}, 1, true
+		}
+		if data[0] >= 32 && data[0] < 127 {
+			return Key{Char: rune(data[0])}, 1, true
+		}
+		return Key{}, 1, true
+	}
+}
