+func NewScreen(w, h int) *Screen {
+	rows := make([][]rune, h)
+	for y := range rows {
+		rows[y] = make([]rune, w)
+		for x := range rows[y] {
+			rows[y][x] = ' '
+		}
+	}
+	return &Screen{W: w, H: h, rows: rows}
+}
+
+func (s *Screen) Set(x, y int, r rune) {
+	if x < 1 || y < 1 || x > s.W || y > s.H {
+		return
+	}
+	s.rows[y-1][x-1] = r
+}
+
+func (s *Screen) Text(x, y int, text string) {
+	for i, r := range []rune(text) {
+		s.Set(x+i, y, r)
+	}
+}
+
+func (s *Screen) Box(x, y, w, h int, title string) {
+	if w < 2 || h < 2 {
+		return
+	}
+	for i := 1; i < w-1; i++ {
+		s.Set(x+i, y, '─')
+		s.Set(x+i, y+h-1, '─')
+	}
+	for i := 1; i < h-1; i++ {
+		s.Set(x, y+i, '│')
+		s.Set(x+w-1, y+i, '│')
+	}
+	s.Set(x, y, '┌')
+	s.Set(x+w-1, y, '┐')
+	s.Set(x, y+h-1, '└')
+	s.Set(x+w-1, y+h-1, '┘')
+	if title != "" {
+		for i, r := range []rune(title) {
+			if i >= w-2 {
+				break
+			}
+			s.Set(x+1+i, y, r)
+		}
+	}
+}
+
+func (s *Screen) String() string {
+	var b strings.Builder
+	for _, row := range s.rows {
+		b.WriteString(string(row))
+		b.WriteByte('\n')
+	}
+	return b.String()
+}
+
+func drawPopupBox(s *Screen, x, y, w, h int, title string, lines []string) {
+	s.Box(x, y, w, h, title)
+	for i, line := range lines {
+		if i >= h-2 {
+			break
+		}
+		s.Text(x+1, y+1+i, center(line, w-2))
+	}
+}
+
+func center(text string, width int) string {
+	runes := []rune(text)
+	if len(runes) >= width {
+		return string(runes[:width])
+	}
+	left := (width - len(runes)) / 2
+	right := width - len(runes) - left
+	return strings.Repeat(" ", left) + text + strings.Repeat(" ", right)
+}
+
+func truncate(text string, max int) string {
+	runes := []rune(text)
+	if len(runes) > max {
+		runes = runes[:max]
+	}
+	return string(runes)
+}
+
+func padRight(text string, width int) string {
+	runes := []rune(text)
+	if len(runes) >= width {
+		return string(runes[:width])
+	}
+	return text + strings.Repeat(" ", width-len(runes))
+}
+
+func parseTags(raw string) []string {
+	parts := strings.Split(raw, ",")
