func main() {
	bin := filepath.Base(os.Args[0])
	cli, resp := parseCLI(bin, os.Args[1:])
	if resp != nil {
		if resp.Stderr {
			fmt.Fprint(os.Stderr, resp.Message)
		} else {
			fmt.Print(resp.Message)
		}
		if resp.Code != 0 {
			os.Exit(resp.Code)
		}
		return
	}

	switch cli.Command.Kind {
	case cmdTheme:
		if err := handleTheme(cli); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	case cmdPrintConfig:
		cfg, err := loadEffectiveConfig(cli)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		fmt.Print(cfg.Render())
	case cmdAssignPriority:
		tty, err := openTTY()
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		defer tty.Close()

		cfg, err := loadEffectiveConfig(cli)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		store, err := NewStore(cfg)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		if err := store.AssignPriority(cli.Command.Priority); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		if err := RunUI(tty, cfg, StartupAction{Kind: "assign"}); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	case cmdImportJournals:
		tty, err := openTTY()
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		defer tty.Close()

		cfg, err := loadEffectiveConfig(cli)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}

		action := StartupAction{Kind: "import"}
		raw, err := os.ReadFile(cli.Command.ImportPath)
		if err != nil {
			action = StartupAction{
				Kind:  "error",
				Title: "Error",
				Lines: []string{fmt.Sprintf("Import file doesn't exist: path %s", cli.Command.ImportPath)},
			}
		} else {
			var transfer ImportedTransfer
			if err := json.Unmarshal(raw, &transfer); err != nil {
				action = StartupAction{
					Kind:  "error",
					Title: "Error",
					Lines: []string{"Error while parsing import file.", fmt.Sprintf("Error: %v", err)},
				}
			} else {
				store, err := NewStore(cfg)
				if err != nil {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					os.Exit(1)
				}
				if err := store.ImportEntries(transfer.Entries); err != nil {
					fmt.Fprintf(os.Stderr, "Error: %v\n", err)
					os.Exit(1)
				}
			}
		}
		if err := RunUI(tty, cfg, action); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	case cmdNone:
		tty, err := openTTY()
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		defer tty.Close()

		cfg, err := loadEffectiveConfig(cli)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
		if err := RunUI(tty, cfg, StartupAction{}); err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	}
}

func parseCLI(bin string, args []string) (CLI, *cliResponse) {
	cli := CLI{BinName: bin, Command: Command{Kind: cmdNone}}
	i := 0
	for i < len(args) {
		arg := args[i]
		switch {
		case arg == "-h" || arg == "--help":
			return cli, &cliResponse{Message: topHelp(bin)}
		case arg == "-V" || arg == "--version":
			return cli, &cliResponse{Message: "tui-journal 0.16.1\n"}
		case arg == "-j" || arg == "--json-file-path":
			i++
			if i >= len(args) {
				return cli, &cliResponse{Code: 2, Stderr: true, Message: missingOptionValue(arg)}
			}
			cli.JSONPath = args[i]
		case arg == "-s" || arg == "--sqlite-file-path":
			i++
			if i >= len(args) {
				return cli, &cliResponse{Code: 2, Stderr: true, Message: missingOptionValue(arg)}
			}
			cli.SQLitePath = args[i]
		case arg == "-b" || arg == "--backend-type":
			i++
			if i >= len(args) {
				return cli, &cliResponse{Code: 2, Stderr: true, Message: missingOptionValue(arg)}
			}
			if args[i] != "json" && args[i] != "sqlite" {
				return cli, &cliResponse{
					Code:   2,
					Stderr: true,
					Message: fmt.Sprintf("error: invalid value '%s' for '--backend-type <BACKEND_TYPE>'\n  [possible values: json, sqlite]\n\nFor more information, try '--help'.\n", args[i]),
				}
			}
			cli.BackendTypeArg = args[i]
		case arg == "-c" || arg == "--config":
			i++
			if i >= len(args) {
				return cli, &cliResponse{Code: 2, Stderr: true, Message: missingOptionValue(arg)}
			}
			cli.ConfigPath = args[i]
		case arg == "-l" || arg == "--log":
			i++
			if i >= len(args) {
				return cli, &cliResponse{Code: 2, Stderr: true, Message: missingOptionValue(arg)}
			}
			cli.LogPath = args[i]
		case strings.HasPrefix(arg, "-v"):
			if arg == "-v" || arg == "-vv" || arg == "-vvv" {
				cli.Verbose += len(arg) - 1
			} else {
				cli.Verbose++
			}
		case arg == "help":
			return cli, parseHelpCommand(bin, args[i+1:])
		case isSubcommand(arg):
			return parseSubcommand(cli, args[i:])
		case strings.HasPrefix(arg, "-"):
			return cli, &cliResponse{
				Code:   2,
				Stderr: true,
				Message: fmt.Sprintf("error: unexpected argument '%s' found\n\nUsage: %s [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.\n", arg, bin),
			}
		default:
			return cli, &cliResponse{
				Code:   2,
				Stderr: true,
				Message: fmt.Sprintf("error: unrecognized subcommand '%s'\n\nUsage: %s [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.\n", arg, bin),
			}
		}
		i++
	}
	return cli, nil
}

func parseHelpCommand(bin string, args []string) *cliResponse {
	if len(args) == 0 {
		return &cliResponse{Message: topHelp(bin)}
	}
	switch normalizeCommand(args[0]) {
	case "theme":
		return &cliResponse{Message: themeHelp(bin)}
	case "print-config":
		return &cliResponse{Message: printConfigHelp(bin)}
	case "import-journals":
		return &cliResponse{Message: importHelp(bin)}
	case "assign-priority":
		return &cliResponse{Message: assignHelp(bin)}
	default:
		return &cliResponse{
			Code:   2,
			Stderr: true,
			Message: fmt.Sprintf("error: unrecognized subcommand '%s'\n\nUsage: %s [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.\n", args[0], bin),
		}
	}
}

func parseSubcommand(cli CLI, args []string) (CLI, *cliResponse) {
	bin := cli.BinName
	switch normalizeCommand(args[0]) {
	case "print-config":
		if len(args) > 1 && (args[1] == "-h" || args[1] == "--help") {
			return cli, &cliResponse{Message: printConfigHelp(bin)}
		}
		cli.Command = Command{Kind: cmdPrintConfig}
		return cli, nil
	case "import-journals":
		if len(args) > 1 && (args[1] == "-h" || args[1] == "--help") {
			return cli, &cliResponse{Message: importHelp(bin)}
		}
		var path string
		for i := 1; i < len(args); i++ {
			switch args[i] {
			case "-p", "--path":
				i++
				if i < len(args) {
					path = args[i]
				}
			}
		}
		if path == "" {
			return cli, &cliResponse{
				Code:   2,
				Stderr: true,
				Message: fmt.Sprintf("error: the following required arguments were not provided:\n  --path <FILE PATH>\n\nUsage: %s import-journals --path <FILE PATH>\n\nFor more information, try '--help'.\n", bin),
			}
		}
		cli.Command = Command{Kind: cmdImportJournals, ImportPath: path}
		return cli, nil
	case "assign-priority":
		if len(args) > 1 && (args[1] == "-h" || args[1] == "--help") {
			return cli, &cliResponse{Message: assignHelp(bin)}
		}
		if len(args) < 2 {
			return cli, &cliResponse{
				Code:   2,
				Stderr: true,
				Message: fmt.Sprintf("error: the following required arguments were not provided:\n  <PRIORITY>\n\nUsage: %s assign-priority <PRIORITY>\n\nFor more information, try '--help'.\n", bin),
			}
		}
		if strings.HasPrefix(args[1], "-") {
			return cli, &cliResponse{
				Code:   2,
				Stderr: true,
				Message: fmt.Sprintf("error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: %s assign-priority <PRIORITY>\n\nFor more information, try '--help'.\n", args[1], args[1], args[1], bin),
			}
		}
		n, err := strconv.ParseUint(args[1], 10, 16)
		if err != nil {
			return cli, &cliResponse{
				Code:   2,
				Stderr: true,
				Message: fmt.Sprintf("error: invalid value '%s' for '<PRIORITY>'\n\nFor more information, try '--help'.\n", args[1]),
			}
		}
		cli.Command = Command{Kind: cmdAssignPriority, Priority: uint16(n)}
		return cli, nil
	case "theme":
		if len(args) == 1 || (len(args) > 1 && (args[1] == "-h" || args[1] == "--help" || args[1] == "help")) {
			return cli, &cliResponse{Message: themeHelp(bin)}
		}
		switch normalizeThemeCommand(args[1]) {
		case "print-path":
			cli.Command = Command{Kind: cmdTheme, ThemeKind: themePrintPath}
		case "print-default":
			cli.Command = Command{Kind: cmdTheme, ThemeKind: themePrintDefault}
		case "write-defaults":
			cli.Command = Command{Kind: cmdTheme, ThemeKind: themeWriteDefaults}
		default:
			return cli, &cliResponse{
				Code:   2,
				Stderr: true,
				Message: fmt.Sprintf("error: unrecognized subcommand '%s'\n\nUsage: %s theme <COMMAND>\n\nFor more information, try '--help'.\n", args[1], bin),
			}
		}
		return cli, nil
	default:
		return cli, &cliResponse{
			Code:   2,
			Stderr: true,
			Message: fmt.Sprintf("error: unrecognized subcommand '%s'\n\nUsage: %s [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.\n", args[0], bin),
		}
	}
}

func isSubcommand(arg string) bool {
	switch normalizeCommand(arg) {
	case "print-config", "import-journals", "assign-priority", "theme":
		return true
	}
	return false
}

func normalizeCommand(arg string) string {
	switch arg {
	case "pc":
		return "print-config"
	case "imj":
		return "import-journals"
	case "ap":
		return "assign-priority"
	case "style":
		return "theme"
	default:
		return arg
	}
}

func normalizeThemeCommand(arg string) string {
	switch arg {
	case "path":
		return "print-path"
	case "default":
		return "print-default"
	case "write":
		return "write-defaults"
	default:
		return arg
	}
}

func missingOptionValue(flag string) string {
	return fmt.Sprintf("error: a value is required for '%s' but none was supplied\n\nFor more information, try '--help'.\n", flag)
}

