func homeDir() string {
	if home := os.Getenv("HOME"); home != "" {
		return home
	}
	return "/"
}

func defaultConfigDir() string {
	return filepath.Join(homeDir(), ".config", "tui-journal")
}

func defaultLogFile() string {
	return filepath.Join(homeDir(), ".cache", "tui-journal", "tui-journal.log")
}

func defaultConfig() Config {
	home := homeDir()
	return Config{
		BackendType:            BackendSQLite,
		ScrollPerPage:          5,
		SyncOSClipboard:        false,
		HistoryLimit:           10,
		ColoredTags:            true,
		DatumVisibility:        "show",
		AppStateDir:            filepath.Join(home, ".local", "state", "tui-journal"),
		ExportShowConfirmation: true,
		ExternalEditorAutoSave: false,
		ExternalEditorTempExt:  "txt",
		JSONBackendFilePath:    filepath.Join(home, "tui-journal", "entries.json"),
		SQLiteBackendFilePath:  filepath.Join(home, "tui-journal", "entries.db"),
	}
}

func loadEffectiveConfig(cli CLI) (Config, error) {
	cfg := defaultConfig()
	if cli.ConfigPath != "" {
		info, err := os.Stat(cli.ConfigPath)
		if err != nil {
			if os.IsNotExist(err) {
				return cfg, fmt.Errorf("Provided custom directory doesn't exit. Path: %s", cli.ConfigPath)
			}
			return cfg, err
		}
		if info.IsDir() {
			configFile := filepath.Join(cli.ConfigPath, "config.toml")
			if _, err := os.Stat(configFile); err == nil {
				if err := parseConfigFile(configFile, &cfg); err != nil {
					return cfg, err
				}
			}
		} else {
			if err := parseConfigFile(cli.ConfigPath, &cfg); err != nil {
				return cfg, err
			}
		}
	}
	if cli.JSONPath != "" {
		cfg.JSONBackendFilePath = cli.JSONPath
	}
	if cli.SQLitePath != "" {
		cfg.SQLiteBackendFilePath = cli.SQLitePath
	}
	if cli.BackendTypeArg != "" {
		if cli.BackendTypeArg == "json" {
			cfg.BackendType = BackendJSON
		} else {
			cfg.BackendType = BackendSQLite
		}
	} else if cli.SQLitePath != "" {
		cfg.BackendType = BackendSQLite
	} else if cli.JSONPath != "" {
		cfg.BackendType = BackendJSON
	}
	return cfg, nil
}

func parseConfigFile(path string, cfg *Config) error {
	f, err := os.Open(path)
	if err != nil {
		return fmt.Errorf("Failed to read configuration file")
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	section := ""
	lineNo := 0
	for scanner.Scan() {
		lineNo++
		raw := scanner.Text()
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		if strings.HasPrefix(trimmed, "[") && strings.HasSuffix(trimmed, "]") {
			section = strings.TrimSpace(trimmed[1 : len(trimmed)-1])
			continue
		}
		parts := strings.SplitN(raw, "=", 2)
		if len(parts) != 2 {
			continue
		}
		key := strings.TrimSpace(parts[0])
		value := strings.TrimSpace(parts[1])
		switch section {
		case "":
			if err := parseTopLevelConfigLine(raw, lineNo, key, value, cfg); err != nil {
				return err
			}
		case "export":
			if key == "show_confirmation" {
				cfg.ExportShowConfirmation = parseBool(value)
			}
		case "external_editor":
			switch key {
			case "auto_save":
				cfg.ExternalEditorAutoSave = parseBool(value)
			case "temp_file_extension":
				cfg.ExternalEditorTempExt = unquote(value)
			}
		case "json_backend":
			if key == "file_path" {
				cfg.JSONBackendFilePath = unquote(value)
			}
		case "sqlite_backend":
			if key == "file_path" {
				cfg.SQLiteBackendFilePath = unquote(value)
			}
		}
	}
	if err := scanner.Err(); err != nil {
		return fmt.Errorf("Failed to read configuration file")
	}
	return nil
}

func parseTopLevelConfigLine(raw string, lineNo int, key, value string, cfg *Config) error {
	switch key {
	case "backend_type":
		v := unquote(value)
		switch v {
		case "Json":
			cfg.BackendType = BackendJSON
		case "Sqlite":
			cfg.BackendType = BackendSQLite
		default:
			column := strings.Index(raw, "\"") + 1
			if column <= 0 {
				column = strings.Index(raw, value) + 1
			}
			caretLen := len(value)
			if caretLen <= 0 {
				caretLen = 1
			}
			return fmt.Errorf("Failed to read configuration file. Error infos: TOML parse error at line %d, column %d\n  |\n%d | %s\n  | %s\nunknown variant `%s`, expected `Json` or `Sqlite`", lineNo, column, lineNo, raw, strings.Repeat(" ", column-1)+strings.Repeat("^", caretLen), v)
		}
	case "scroll_per_page":
		cfg.ScrollPerPage = parseInt(value)
	case "sync_os_clipboard":
		cfg.SyncOSClipboard = parseBool(value)
	case "history_limit":
		cfg.HistoryLimit = parseInt(value)
	case "colored_tags":
		cfg.ColoredTags = parseBool(value)
	case "datum_visibility":
		cfg.DatumVisibility = unquote(value)
	case "app_state_dir":
		cfg.AppStateDir = unquote(value)
	}
	return nil
}

func parseBool(value string) bool {
	return strings.TrimSpace(value) == "true"
}

func parseInt(value string) int {
	n, _ := strconv.Atoi(strings.TrimSpace(value))
	return n
}

func unquote(value string) string {
	value = strings.TrimSpace(value)
	if len(value) >= 2 && value[0] == '"' && value[len(value)-1] == '"' {
		return value[1 : len(value)-1]
	}
	return value
}

