func handleTheme(cli CLI) error {
	target, err := resolveThemeTarget(cli.ConfigPath)
	if err != nil {
		return err
	}
	if target.IgnoredNonDir {
		fmt.Println("INFO: Custom config directory is ignored in themese because it's not a directory.")
	}
	switch cli.Command.ThemeKind {
	case themePrintPath:
		fmt.Println(target.ThemePath)
	case themePrintDefault:
		fmt.Print(defaultTheme)
	case themeWriteDefaults:
		if err := writeDefaultTheme(target.ThemePath); err != nil {
			return err
		}
		fmt.Printf("Default themes have been written to %s\n", target.ThemePath)
	}
	return nil
}

func resolveThemeTarget(configPath string) (ThemeTarget, error) {
	defaultPath := filepath.Join(defaultConfigDir(), "themes.toml")
	if configPath == "" {
		return ThemeTarget{ThemePath: defaultPath}, nil
	}
	info, err := os.Stat(configPath)
	if err != nil {
		if os.IsNotExist(err) {
			return ThemeTarget{}, fmt.Errorf("Provided custom directory doesn't exit. Path: %s", configPath)
		}
		return ThemeTarget{}, err
	}
	if info.IsDir() {
		return ThemeTarget{ThemePath: filepath.Join(configPath, "themes.toml")}, nil
	}
	return ThemeTarget{ThemePath: defaultPath, IgnoredNonDir: true}, nil
}

func writeDefaultTheme(path string) error {
	if _, err := os.Stat(path); err == nil {
		return fmt.Errorf("Themes file already exists. Path: %s", path)
	}
	if err := os.WriteFile(path, []byte(defaultTheme), 0644); err != nil {
		return fmt.Errorf("Error while writing default themes to file\n\nCaused by:\n    %s", formatErrOnly(err))
	}
	return nil
}

func openTTY() (*os.File, error) {
	f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return nil, fmt.Errorf(formatErrOnly(err))
	}
	return f, nil
}

func formatErrOnly(err error) string {
	if pe, ok := err.(*os.PathError); ok {
		if errno, ok := pe.Err.(syscall.Errno); ok {
			return formatErrno(errno)
		}
		return pe.Err.Error()
	}
	if errno, ok := err.(syscall.Errno); ok {
		return formatErrno(errno)
	}
	return err.Error()
}

func formatErrno(errno syscall.Errno) string {
	msg := errno.Error()
	if msg == "" {
		return fmt.Sprintf("os error %d", errno)
	}
	return strings.ToUpper(msg[:1]) + msg[1:] + fmt.Sprintf(" (os error %d)", errno)
}

func (d DateOnly) MarshalJSON() ([]byte, error) {
	return json.Marshal(d.Format("2006-01-02T00:00:00Z"))
}

func (d *DateOnly) UnmarshalJSON(data []byte) error {
	var raw string
	if err := json.Unmarshal(data, &raw); err != nil {
		return err
	}
	t, err := time.Parse(time.RFC3339, raw)
	if err != nil {
		return err
	}
	d.Time = t.UTC()
	return nil
}

func parseDateOnly(raw string) (DateOnly, error) {
	if strings.Contains(raw, "T") {
		t, err := time.Parse(time.RFC3339, raw)
		if err != nil {
			return DateOnly{}, err
		}
		return DateOnly{Time: t.UTC()}, nil
	}
	t, err := time.Parse("02-01-2006", raw)
	if err != nil {
		return DateOnly{}, err
	}
	return DateOnly{Time: time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, time.UTC)}, nil
}

func todayDateOnly() DateOnly {
	now := time.Now().UTC()
	return DateOnly{Time: time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, time.UTC)}
}

func (d DateOnly) FormDate() string {
	return d.Format("02-01-2006")
}

func (d DateOnly) ListDate() string {
	return fmt.Sprintf("%d,%d,%d", d.Day(), int(d.Month()), d.Year())
}

func (d DateOnly) SQLiteString() string {
	return d.Format("2006-01-02T00:00:00+00:00")
}

func NewStore(cfg Config) (Store, error) {
	if cfg.BackendType == BackendJSON {
		return &JSONStore{Path: cfg.JSONBackendFilePath}, nil
	}
	return NewSQLiteStore(cfg.SQLiteBackendFilePath)
}

func (s *JSONStore) LoadEntries() ([]Entry, error) {
	raw, err := os.ReadFile(s.Path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	if len(raw) == 0 {
		return nil, nil
	}
	var entries []Entry
	if err := json.Unmarshal(raw, &entries); err != nil {
		return nil, err
	}
	return entries, nil
}

func (s *JSONStore) save(entries []Entry) error {
	raw, err := json.Marshal(entries)
	if err != nil {
		return err
	}
	return os.WriteFile(s.Path, raw, 0644)
}

func (s *JSONStore) CreateEntry(title string, date DateOnly, priority *uint16, tags []string) (Entry, error) {
	entries, err := s.LoadEntries()
	if err != nil {
		return Entry{}, err
	}
	var next uint64
	for _, entry := range entries {
		if entry.ID >= next {
			next = entry.ID + 1
		}
	}
	entry := Entry{ID: next, Date: date, Title: title, Content: "", Tags: tags, Priority: priority}
	entries = append(entries, entry)
	return entry, s.save(entries)
}

func (s *JSONStore) UpdateEntry(entry Entry) error {
	entries, err := s.LoadEntries()
	if err != nil {
		return err
	}
	for i := range entries {
		if entries[i].ID == entry.ID {
			entries[i] = entry
			break
		}
	}
	return s.save(entries)
}

func (s *JSONStore) UpdateEntryContent(id uint64, content string) error {
	entries, err := s.LoadEntries()
	if err != nil {
		return err
	}
	for i := range entries {
		if entries[i].ID == id {
			entries[i].Content = content
			break
		}
	}
	return s.save(entries)
}

func (s *JSONStore) DeleteEntry(id uint64) error {
	entries, err := s.LoadEntries()
	if err != nil {
		return err
	}
	out := make([]Entry, 0, len(entries))
	for _, entry := range entries {
		if entry.ID != id {
			out = append(out, entry)
		}
	}
	return s.save(out)
}

func (s *JSONStore) AssignPriority(v uint16) error {
	entries, err := s.LoadEntries()
	if err != nil {
		return err
	}
	for i := range entries {
		if entries[i].Priority == nil {
			value := v
			entries[i].Priority = &value
		}
	}
	return s.save(entries)
}

func (s *JSONStore) ImportEntries(entries []Entry) error {
	current, err := s.LoadEntries()
	if err != nil {
		return err
	}
	var next uint64
	for _, entry := range current {
		if entry.ID >= next {
			next = entry.ID + 1
		}
	}
	for _, entry := range entries {
		entry.ID = next
		next++
		current = append(current, entry)
	}
	return s.save(current)
}

func NewSQLiteStore(path string) (*SQLiteStore, error) {
	s := &SQLiteStore{Path: path}
	if err := s.initialize(); err != nil {
		return nil, err
	}
	return s, nil
}

func (s *SQLiteStore) open() (*C.sqlite3, error) {
	cpath := C.CString(s.Path)
	defer C.free(unsafe.Pointer(cpath))
	var db *C.sqlite3
	if rc := C.sqlite3_open(cpath, &db); rc != sqliteOK {
		if db != nil {
			defer C.sqlite3_close(db)
			return nil, fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db)))
		}
		return nil, fmt.Errorf("sqlite open error")
	}
	if err := execSQL(db, "PRAGMA foreign_keys = ON;"); err != nil {
		C.sqlite3_close(db)
		return nil, err
	}
	return db, nil
}

func (s *SQLiteStore) initialize() error {
	db, err := s.open()
	if err != nil {
		return err
	}
	defer C.sqlite3_close(db)

	schema := `
CREATE TABLE IF NOT EXISTS _sqlx_migrations (
    version BIGINT PRIMARY KEY,
    description TEXT NOT NULL,
    installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    success BOOLEAN NOT NULL,
    checksum BLOB NOT NULL,
    execution_time BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS entries
(
  id        INTEGER PRIMARY KEY  NOT NULL,
  title     TEXT                 NOT NULL,
  date      DATE                 NOT NULL,
  content   TEXT
, priority INTEGER DEFAULT NULL);
CREATE TABLE IF NOT EXISTS tags (
  entry_id INTEGER NOT NULL,
  tag TEXT NOT NULL,
  PRIMARY KEY (entry_id, tag),
  FOREIGN KEY (entry_id) REFERENCES entries (id) ON DELETE CASCADE
);
`
	if err := execSQL(db, schema); err != nil {
		return err
	}
	migrations := []string{
		"INSERT OR IGNORE INTO _sqlx_migrations (version, description, success, checksum, execution_time) VALUES (20230509041613, 'init entries', 1, X'a9b962e074e56db0fbfbcf4874ed6d1e8d94313c9c0122247465cc26057ad3635235b208703db8a0843a8bc16cd50685', 217287);",
		"INSERT OR IGNORE INTO _sqlx_migrations (version, description, success, checksum, execution_time) VALUES (20230613041405, 'add tags', 1, X'e0eb5fd4d092c82cb2bd4528ce27fe9c037f045245ac9f1235ee2cef07c75443e8fec98c3a5f0562c641b1bc5301f319', 267302);",
		"INSERT OR IGNORE INTO _sqlx_migrations (version, description, success, checksum, execution_time) VALUES (20240104160740, 'entries priorities', 1, X'4dc4e4c3a2cd7adf8ca6ee6cca5a84eaa929bbb9c4969af5bc181a992095e61aa156dab76718437fccd99e7fa1a75f7c', 321234);",
	}
	for _, stmt := range migrations {
		if err := execSQL(db, stmt); err != nil {
			return err
		}
	}
	return nil
}

func (s *SQLiteStore) LoadEntries() ([]Entry, error) {
	db, err := s.open()
	if err != nil {
		return nil, err
	}
	defer C.sqlite3_close(db)

	rows, err := queryRows(db, "SELECT id, title, date, COALESCE(content, ''), COALESCE(priority, -1) FROM entries ORDER BY id ASC;", 5)
	if err != nil {
		return nil, err
	}
	entries := make([]Entry, 0, len(rows))
	for _, row := range rows {
		date, err := parseDateOnly(row[2])
		if err != nil {
			return nil, err
		}
		entry := Entry{
			ID:      parseUint64(row[0]),
			Title:   row[1],
			Date:    date,
			Content: row[3],
		}
		if row[4] != "-1" {
			value := uint16(parseInt64(row[4]))
			entry.Priority = &value
		}
		tagRows, err := queryRows(db, fmt.Sprintf("SELECT tag FROM tags WHERE entry_id = %d ORDER BY tag COLLATE NOCASE ASC;", entry.ID), 1)
		if err != nil {
			return nil, err
		}
		for _, tag := range tagRows {
			entry.Tags = append(entry.Tags, tag[0])
		}
		entries = append(entries, entry)
	}
	return entries, nil
}

func (s *SQLiteStore) CreateEntry(title string, date DateOnly, priority *uint16, tags []string) (Entry, error) {
	db, err := s.open()
	if err != nil {
		return Entry{}, err
	}
	defer C.sqlite3_close(db)
	prioritySQL := "NULL"
	if priority != nil {
		prioritySQL = fmt.Sprintf("%d", *priority)
	}
	if err := execSQL(db, fmt.Sprintf("INSERT INTO entries (title, date, content, priority) VALUES ('%s', '%s', '', %s);", sqlQuote(title), date.SQLiteString(), prioritySQL)); err != nil {
		return Entry{}, err
	}
	id := uint64(C.sqlite3_last_insert_rowid(db))
	if err := replaceTags(db, id, tags); err != nil {
		return Entry{}, err
	}
	return Entry{ID: id, Title: title, Date: date, Content: "", Tags: tags, Priority: priority}, nil
}

func (s *SQLiteStore) UpdateEntry(entry Entry) error {
	db, err := s.open()
	if err != nil {
		return err
	}
	defer C.sqlite3_close(db)
	prioritySQL := "NULL"
	if entry.Priority != nil {
		prioritySQL = fmt.Sprintf("%d", *entry.Priority)
	}
	if err := execSQL(db, fmt.Sprintf("UPDATE entries SET title = '%s', date = '%s', content = '%s', priority = %s WHERE id = %d;", sqlQuote(entry.Title), entry.Date.SQLiteString(), sqlQuote(entry.Content), prioritySQL, entry.ID)); err != nil {
		return err
	}
	return replaceTags(db, entry.ID, entry.Tags)
}

func (s *SQLiteStore) UpdateEntryContent(id uint64, content string) error {
	db, err := s.open()
	if err != nil {
		return err
	}
	defer C.sqlite3_close(db)
	return execSQL(db, fmt.Sprintf("UPDATE entries SET content = '%s' WHERE id = %d;", sqlQuote(content), id))
}

func (s *SQLiteStore) DeleteEntry(id uint64) error {
	db, err := s.open()
	if err != nil {
		return err
	}
	defer C.sqlite3_close(db)
	return execSQL(db, fmt.Sprintf("DELETE FROM entries WHERE id = %d;", id))
}

func (s *SQLiteStore) AssignPriority(v uint16) error {
	db, err := s.open()
	if err != nil {
		return err
	}
	defer C.sqlite3_close(db)
	return execSQL(db, fmt.Sprintf("UPDATE entries SET priority = %d WHERE priority IS NULL;", v))
}

func (s *SQLiteStore) ImportEntries(entries []Entry) error {
	db, err := s.open()
	if err != nil {
		return err
	}
	defer C.sqlite3_close(db)
	for _, entry := range entries {
		prioritySQL := "NULL"
		if entry.Priority != nil {
			prioritySQL = fmt.Sprintf("%d", *entry.Priority)
		}
		if err := execSQL(db, fmt.Sprintf("INSERT INTO entries (title, date, content, priority) VALUES ('%s', '%s', '%s', %s);", sqlQuote(entry.Title), entry.Date.SQLiteString(), sqlQuote(entry.Content), prioritySQL)); err != nil {
			return err
		}
		id := uint64(C.sqlite3_last_insert_rowid(db))
		if err := replaceTags(db, id, entry.Tags); err != nil {
			return err
		}
	}
	return nil
}

func replaceTags(db *C.sqlite3, entryID uint64, tags []string) error {
	if err := execSQL(db, fmt.Sprintf("DELETE FROM tags WHERE entry_id = %d;", entryID)); err != nil {
		return err
	}
	for _, tag := range tags {
		if err := execSQL(db, fmt.Sprintf("INSERT INTO tags (entry_id, tag) VALUES (%d, '%s');", entryID, sqlQuote(tag))); err != nil {
			return err
		}
	}
	return nil
}

func execSQL(db *C.sqlite3, sql string) error {
	csql := C.CString(sql)
	defer C.free(unsafe.Pointer(csql))
	var errmsg *C.char
	rc := C.sqlite3_exec(db, csql, nil, nil, &errmsg)
	if rc != sqliteOK {
		if errmsg != nil {
			defer C.sqlite3_free(unsafe.Pointer(errmsg))
			return fmt.Errorf("%s", C.GoString(errmsg))
		}
		return fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db)))
	}
	return nil
}

func queryRows(db *C.sqlite3, sql string, cols int) ([][]string, error) {
	csql := C.CString(sql)
	defer C.free(unsafe.Pointer(csql))
	var stmt *C.sqlite3_stmt
	if rc := C.sqlite3_prepare_v2(db, csql, -1, &stmt, nil); rc != sqliteOK {
		return nil, fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db)))
	}
	defer C.sqlite3_finalize(stmt)

	var rows [][]string
	for {
		rc := C.sqlite3_step(stmt)
		if rc == sqliteDone {
			break
		}
		if rc != sqliteRow {
			return nil, fmt.Errorf("%s", C.GoString(C.sqlite3_errmsg(db)))
		}
		row := make([]string, cols)
		for i := 0; i < cols; i++ {
			text := C.sqlite3_column_text(stmt, C.int(i))
			if text != nil {
				row[i] = C.GoString((*C.char)(unsafe.Pointer(text)))
			}
		}
		rows = append(rows, row)
	}
	return rows, nil
}

func sqlQuote(value string) string {
	return strings.ReplaceAll(value, "'", "''")
}

func sortEntries(entries []Entry, descending bool) []Entry {
	out := append([]Entry(nil), entries...)
	sort.SliceStable(out, func(i, j int) bool {
		left, right := out[i], out[j]
		if descending {
			if !left.Date.Equal(right.Date.Time) {
				return left.Date.After(right.Date.Time)
			}
			lp, rp := -1, -1
			if left.Priority != nil {
				lp = int(*left.Priority)
			}
			if right.Priority != nil {
				rp = int(*right.Priority)
			}
			if lp != rp {
				return lp > rp
			}
			return left.ID < right.ID
		}
		if !left.Date.Equal(right.Date.Time) {
			return left.Date.Before(right.Date.Time)
		}
		lp, rp := -1, -1
		if left.Priority != nil {
			lp = int(*left.Priority)
		}
		if right.Priority != nil {
			rp = int(*right.Priority)
		}
		if lp != rp {
			return lp < rp
		}
		return left.ID < right.ID
	})
	return out
}

func RunUI(tty *os.File, cfg Config, action StartupAction) error {
	restore, err := enableRawTTY()
	if err != nil {
		return err
	}
	defer restore()

	fmt.Fprint(tty, "\x1b[?1049h\x1b[?25l")
	defer fmt.Fprint(tty, "\x1b[?1049l\x1b[?25h")

	store, err := NewStore(cfg)
	if err != nil {
		return err
	}
	entries, err := store.LoadEntries()
	if err != nil {
		return err
	}

	app := &UIApp{
		store:          store,
		entries:        entries,
		sortDescending: true,
	}
	switch action.Kind {
	case "assign":
		app.transientLines = []string{"Assigning Priority to Journals..."}
		app.transientUntil = time.Now().Add(350 * time.Millisecond)
	case "import":
		app.transientLines = []string{"Importing journals..."}
		app.transientUntil = time.Now().Add(350 * time.Millisecond)
	case "error":
		app.popup = popupState{Kind: "error", Title: action.Title, Lines: action.Lines}
	}
	if len(app.visibleEntries()) == 0 {
		app.selected = 0
	}
	return app.loop(tty)
}

func enableRawTTY() (func(), error) {
	cmd := exec.Command("stty", "-F", "/dev/tty", "raw", "-echo", "min", "0", "time", "1")
	if out, err := cmd.CombinedOutput(); err != nil {
		return nil, fmt.Errorf("%v: %s", err, string(out))
	}
	return func() {
		_ = exec.Command("stty", "-F", "/dev/tty", "sane").Run()
	}, nil
}

func (a *UIApp) loop(tty *os.File) error {
	for {
		if !a.transientUntil.IsZero() && time.Now().After(a.transientUntil) {
			a.transientUntil = time.Time{}
			a.transientLines = nil
		}
		if err := a.draw(tty); err != nil {
			return err
		}
		key, ok, err := a.readKey(tty)
		if err != nil {
			return err
		}
		if !ok {
			continue
		}
		exit, err := a.handleKey(key)
		if err != nil {
			return err
		}
		if exit {
			return nil
		}
	}
}

func (a *UIApp) draw(w io.Writer) error {
	screen := NewScreen(80, 24)
	a.drawMain(screen)
	if !a.transientUntil.IsZero() && len(a.transientLines) > 0 {
		drawPopupBox(screen, 23, 11, 35, 3, "", a.transientLines)
	}
	switch a.mode {
	case modeForm:
		a.drawForm(screen)
	case modeFilter:
		a.drawFilter(screen)
	case modeSort:
		a.drawSort(screen)
	case modeHelp:
		a.drawHelp(screen)
	}
	if a.popup.Kind != "" {
		a.drawPopup(screen)
	}
	_, err := fmt.Fprintf(w, "\x1b[H%s", screen.String())
	return err
}

func (a *UIApp) drawMain(s *Screen) {
	s.Box(1, 1, 24, 22, "Journals")
	visible := a.visibleEntries()
	if len(visible) > 0 {
		count := fmt.Sprintf("%d/%d", a.selected+1, len(visible))
		s.Text(24-len(count)-1, 22, count)
	}

	contentTitle := "Content"
	if a.mode == modeEditorInsert {
		contentTitle = "Content - EDIT"
		if a.editor != nil && a.editor.Dirty {
			contentTitle += " *"
		}
	} else if a.mode == modeEditorNormal {
		contentTitle = "Content - NORMAL"
		if a.editor != nil && a.editor.Dirty {
			contentTitle += " *"
		}
	}
	s.Box(24, 1, 57, 22, contentTitle)

	if len(visible) == 0 {
		s.Text(3, 3, "Use 'n' to create new")
		s.Text(10, 4, "entry")
	} else {
		y := 2
		for i, entry := range visible {
			prefix := "  "
			if i == a.selected {
				prefix = "> "
			}
			s.Text(2, y, padRight(prefix+truncate(entry.Title, 20), 22))
			y++
			s.Text(2, y, padRight("  "+entry.Date.ListDate(), 22))
			y++
			if entry.Priority != nil {
				s.Text(2, y, padRight(fmt.Sprintf("  Priority: %d", *entry.Priority), 22))
				y++
			}
			if len(entry.Tags) > 0 {
				s.Text(2, y, padRight("  "+strings.Join(entry.Tags, ", "), 22))
				y++
			}
			if y > 21 {
				break
			}
		}
	}

	content := ""
	if a.mode == modeEditorInsert || a.mode == modeEditorNormal {
		content = a.editor.Buffer
	} else if len(visible) > 0 {
		content = visible[a.selected].Content
	}
	lines := strings.Split(content, "\n")
	for i, line := range lines {
		if i >= 20 {
			break
		}
		s.Text(26, 2+i, truncate(line, 54))
	}

	if a.mode == modeEditorInsert {
		s.Text(1, 23, padRight("Back to Editor Normal Mode: 'Esc','<Ctrl-c>','<Ctrl-[>' |  Edit using Emacs motions", 80))
	} else if a.mode == modeEditorNormal {
		s.Text(1, 24, padRight("Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Show help: '?'", 80))
	} else {
		s.Text(1, 23, padRight("Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Open filter: 'f' | Open", 80))
		s.Text(1, 24, padRight("sort options: 'o' | Show help: '?'", 80))
	}
}

