func (a *UIApp) handleKey(k Key) (bool, error) {
	if a.popup.Kind != "" {
		return a.handlePopupKey(k)
	}
	switch a.mode {
	case modeMain:
		return a.handleMainKey(k)
	case modeForm:
		return false, a.handleFormKey(k)
	case modeEditorInsert:
		return false, a.handleEditorInsertKey(k)
	case modeEditorNormal:
		return a.handleEditorNormalKey(k)
	case modeFilter:
		a.handleFilterKey(k)
	case modeSort:
		a.handleSortKey(k)
	case modeHelp:
		a.handleHelpKey(k)
	}
	return false, nil
}

func (a *UIApp) handlePopupKey(k Key) (bool, error) {
	switch a.popup.Kind {
	case "delete":
		if k.Char == 'y' || k.Char == 'Y' {
			visible := a.visibleEntries()
			if len(visible) > 0 {
				if err := a.store.DeleteEntry(visible[a.selected].ID); err != nil {
					return false, err
				}
				if err := a.reload(); err != nil {
					return false, err
				}
			}
			a.popup = popupState{}
		} else if k.Char == 'n' || k.Char == 'N' || k.Name == "esc" {
			a.popup = popupState{}
		}
	case "save":
		if k.Char == 'y' || k.Char == 'Y' {
			if err := a.store.UpdateEntryContent(a.editor.EntryID, a.editor.Buffer); err != nil {
				return false, err
			}
			return true, nil
		}
		if k.Char == 'n' || k.Char == 'N' {
			return true, nil
		}
		if k.Char == 'c' || k.Char == 'C' || k.Name == "esc" {
			a.popup = popupState{}
		}
	case "error":
		if k.Name == "enter" {
			a.popup = popupState{}
		}
	}
	return false, nil
}

func (a *UIApp) handleMainKey(k Key) (bool, error) {
	switch {
	case k.Char == 'q':
		return true, nil
	case k.Name == "down" || k.Char == 'j':
		a.moveSelection(1)
	case k.Name == "up" || k.Char == 'k':
		a.moveSelection(-1)
	case k.Char == 'n':
		a.mode = modeForm
		a.form = &FormState{Mode: "create", Date: todayDateOnly().FormDate()}
	case k.Char == 'e':
		visible := a.visibleEntries()
		if len(visible) > 0 {
			entry := visible[a.selected]
			a.mode = modeForm
			a.form = &FormState{
				Mode:     "edit",
				EntryID:  entry.ID,
				Title:    entry.Title,
				Date:     entry.Date.FormDate(),
				Priority: priorityString(entry.Priority),
				Tags:     strings.Join(entry.Tags, ","),
				Content:  entry.Content,
			}
		}
	case k.Char == 'd':
		if len(a.visibleEntries()) > 0 {
			a.popup = popupState{Kind: "delete"}
		}
	case k.Name == "enter":
		visible := a.visibleEntries()
		if len(visible) > 0 {
			entry := visible[a.selected]
			a.mode = modeEditorInsert
			a.editor = &EditorState{EntryID: entry.ID, Buffer: entry.Content}
		}
	case k.Char == 'f':
		a.mode = modeFilter
		copyState := a.filter
		a.filterDialog = &copyState
	case k.Char == 'o':
		a.mode = modeSort
		a.sortDialog = &SortState{Descending: a.sortDescending}
	case k.Char == '?':
		a.mode = modeHelp
		a.helpDialog = &HelpState{}
	}
	return false, nil
}

func (a *UIApp) handleFormKey(k Key) error {
	switch {
	case k.Name == "esc" || k.Name == "ctrl-c":
		a.mode = modeMain
	case k.Name == "tab":
		a.form.Focus = (a.form.Focus + 1) % 4
	case k.Name == "backspace":
		field := a.activeFormField()
		if len(*field) > 0 {
			*field = (*field)[:len(*field)-1]
		}
		a.form.ErrField, a.form.ErrMsg = "", ""
	case k.Name == "enter":
		if strings.TrimSpace(a.form.Title) == "" {
			a.form.ErrField, a.form.ErrMsg = "title", "Title can't be empty"
			return nil
		}
		date, err := parseDateOnly(a.form.Date)
		if err != nil || !isDateInputValid(a.form.Date) {
			a.form.ErrField, a.form.ErrMsg = "date", "input contains invalid characters"
			return nil
		}
		var priority *uint16
		if strings.TrimSpace(a.form.Priority) != "" {
			n, err := strconv.ParseUint(a.form.Priority, 10, 16)
			if err != nil {
				a.form.ErrField, a.form.ErrMsg = "priority", "input contains invalid characters"
				return nil
			}
			value := uint16(n)
			priority = &value
		}
		tags := parseTags(a.form.Tags)
		if a.form.Mode == "create" {
			if _, err := a.store.CreateEntry(a.form.Title, date, priority, tags); err != nil {
				return err
			}
		} else {
			entry := Entry{
				ID:       a.form.EntryID,
				Title:    a.form.Title,
				Date:     date,
				Content:  a.form.Content,
				Tags:     tags,
				Priority: priority,
			}
			if err := a.store.UpdateEntry(entry); err != nil {
				return err
			}
		}
		if err := a.reload(); err != nil {
			return err
		}
		a.mode = modeMain
	case k.Char != 0:
		field := a.activeFormField()
		*field += string(k.Char)
		a.form.ErrField, a.form.ErrMsg = "", ""
		if a.form.Focus == 1 && !isDateInputValid(a.form.Date) {
			a.form.ErrField, a.form.ErrMsg = "date", "input contains invalid characters"
		}
		if a.form.Focus == 2 && !isDigits(a.form.Priority) {
			a.form.ErrField, a.form.ErrMsg = "priority", "input contains invalid characters"
		}
	}
	return nil
}

func (a *UIApp) handleEditorInsertKey(k Key) error {
	switch {
	case k.Name == "esc" || k.Name == "ctrl-c":
		a.mode = modeEditorNormal
	case k.Name == "ctrl-s":
		if err := a.store.UpdateEntryContent(a.editor.EntryID, a.editor.Buffer); err != nil {
			return err
		}
		a.editor.Dirty = false
		return a.reload()
	case k.Name == "backspace":
		if len(a.editor.Buffer) > 0 {
			a.editor.Buffer = a.editor.Buffer[:len(a.editor.Buffer)-1]
			a.editor.Dirty = true
		}
	case k.Name == "enter":
		a.editor.Buffer += "\n"
		a.editor.Dirty = true
	case k.Char != 0:
		a.editor.Buffer += string(k.Char)
		a.editor.Dirty = true
	}
	return nil
}

func (a *UIApp) handleEditorNormalKey(k Key) (bool, error) {
	switch {
	case k.Char == 'q':
		if a.editor.Dirty {
			a.popup = popupState{Kind: "save"}
			return false, nil
		}
		return true, nil
	case k.Name == "enter":
		a.mode = modeEditorInsert
	case k.Char == '?':
		a.mode = modeHelp
		a.helpDialog = &HelpState{Tab: 1}
	case k.Char == 's':
		if err := a.store.UpdateEntryContent(a.editor.EntryID, a.editor.Buffer); err != nil {
			return false, err
		}
		a.editor.Dirty = false
		if err := a.reload(); err != nil {
			return false, err
		}
	}
	return false, nil
}

func (a *UIApp) handleFilterKey(k Key) {
	switch {
	case k.Name == "esc" || k.Name == "ctrl-c":
		a.mode = modeMain
	case k.Name == "tab":
		a.filterDialog.Focus = (a.filterDialog.Focus + 1) % 5
	case k.Name == "enter":
		a.filter = *a.filterDialog
		a.adjustSelection()
		a.mode = modeMain
	case k.Name == "ctrl-r":
		a.filterDialog.And = !a.filterDialog.And
	case k.Name == "backspace":
		switch a.filterDialog.Focus {
		case 1:
			if len(a.filterDialog.Title) > 0 {
				a.filterDialog.Title = a.filterDialog.Title[:len(a.filterDialog.Title)-1]
			}
		case 2:
			if len(a.filterDialog.Content) > 0 {
				a.filterDialog.Content = a.filterDialog.Content[:len(a.filterDialog.Content)-1]
			}
		case 3:
			if len(a.filterDialog.Priority) > 0 {
				a.filterDialog.Priority = a.filterDialog.Priority[:len(a.filterDialog.Priority)-1]
			}
		}
	case k.Name == "space" && a.filterDialog.Focus == 4:
		tags := a.availableTags()
		if len(tags) > 0 {
			tag := tags[0]
			if containsString(a.filterDialog.Tags, tag) {
				a.filterDialog.Tags = removeString(a.filterDialog.Tags, tag)
			} else {
				a.filterDialog.Tags = append(a.filterDialog.Tags, tag)
			}
		}
	case k.Char != 0:
		switch a.filterDialog.Focus {
		case 1:
			a.filterDialog.Title += string(k.Char)
		case 2:
			a.filterDialog.Content += string(k.Char)
		case 3:
			a.filterDialog.Priority += string(k.Char)
		}
	}
}

func (a *UIApp) handleSortKey(k Key) {
	switch {
	case k.Name == "esc" || k.Name == "ctrl-c":
		a.mode = modeMain
	case k.Name == "enter":
		a.sortDescending = a.sortDialog.Descending
		a.adjustSelection()
		a.mode = modeMain
	case k.Char == 'o':
		a.sortDialog.Descending = !a.sortDialog.Descending
	case k.Name == "ctrl-d":
		a.sortDialog.Descending = true
	}
}

func (a *UIApp) handleHelpKey(k Key) {
	switch {
	case k.Name == "esc" || k.Char == '?':
		a.mode = modeMain
	case k.Name == "tab" || k.Name == "ctrl-l":
		a.helpDialog.Tab = (a.helpDialog.Tab + 1) % 3
	case k.Name == "backtab" || k.Name == "ctrl-h":
		a.helpDialog.Tab = (a.helpDialog.Tab + 2) % 3
	}
}

func (a *UIApp) activeFormField() *string {
	switch a.form.Focus {
	case 0:
		return &a.form.Title
	case 1:
		return &a.form.Date
	case 2:
		return &a.form.Priority
	default:
		return &a.form.Tags
	}
}

func (a *UIApp) reload() error {
	entries, err := a.store.LoadEntries()
	if err != nil {
		return err
	}
	a.entries = entries
	a.adjustSelection()
	return nil
}

func (a *UIApp) adjustSelection() {
	visible := a.visibleEntries()
	if len(visible) == 0 {
		a.selected = 0
		return
	}
	if a.selected >= len(visible) {
		a.selected = len(visible) - 1
	}
	if a.selected < 0 {
		a.selected = 0
	}
}

func (a *UIApp) moveSelection(delta int) {
	visible := a.visibleEntries()
	if len(visible) == 0 {
		a.selected = 0
		return
	}
	a.selected += delta
	if a.selected < 0 {
		a.selected = 0
	}
	if a.selected >= len(visible) {
		a.selected = len(visible) - 1
	}
}

func (a *UIApp) visibleEntries() []Entry {
	entries := sortEntries(a.entries, a.sortDescending)
	out := make([]Entry, 0, len(entries))
	for _, entry := range entries {
		if a.filterMatch(entry) {
			out = append(out, entry)
		}
	}
	return out
}

func (a *UIApp) filterMatch(entry Entry) bool {
	checks := []bool{}
	if a.filter.Title != "" {
		checks = append(checks, strings.Contains(strings.ToLower(entry.Title), strings.ToLower(a.filter.Title)))
	}
	if a.filter.Content != "" {
		checks = append(checks, strings.Contains(strings.ToLower(entry.Content), strings.ToLower(a.filter.Content)))
	}
	if a.filter.Priority != "" {
		checks = append(checks, priorityString(entry.Priority) == a.filter.Priority)
	}
	if len(a.filter.Tags) > 0 {
		matches := true
		for _, tag := range a.filter.Tags {
			if !containsString(entry.Tags, tag) {
				matches = false
				break
			}
		}
		checks = append(checks, matches)
	}
	if len(checks) == 0 {
		return true
	}
	if a.filter.And {
		for _, check := range checks {
			if !check {
				return false
			}
		}
		return true
	}
	for _, check := range checks {
		if check {
			return true
		}
	}
	return false
}

func (a *UIApp) availableTags() []string {
	set := map[string]bool{}
	for _, entry := range a.entries {
		for _, tag := range entry.Tags {
			set[tag] = true
		}
	}
	out := make([]string, 0, len(set))
	for tag := range set {
		out = append(out, tag)
	}
	sort.Slice(out, func(i, j int) bool {
		return strings.ToLower(out[i]) < strings.ToLower(out[j])
	})
	return out
}

func (a *UIApp) readKey(tty *os.File) (Key, bool, error) {
	buf := make([]byte, 16)
	n, err := tty.Read(buf)
	if err != nil && err != io.EOF {
		return Key{}, false, err
	}
	if n > 0 {
		a.rx = append(a.rx, buf[:n]...)
	}
	if len(a.rx) == 0 {
		return Key{}, false, nil
	}
	key, used, ok := parseKeyBytes(a.rx)
	if !ok {
		return Key{}, false, nil
	}
	a.rx = a.rx[used:]
	return key, true, nil
}

func parseKeyBytes(data []byte) (Key, int, bool) {
	if len(data) == 0 {
		return Key{}, 0, false
	}
	switch data[0] {
	case 0:
		return Key{Name: "ctrl-space"}, 1, true
	case 3:
		return Key{Name: "ctrl-c"}, 1, true
	case 4:
		return Key{Name: "ctrl-d"}, 1, true
	case 8:
		return Key{Name: "ctrl-h"}, 1, true
	case 9:
		return Key{Name: "tab"}, 1, true
	case 10, 13:
		return Key{Name: "enter"}, 1, true
	case 12:
		return Key{Name: "ctrl-l"}, 1, true
	case 18:
		return Key{Name: "ctrl-r"}, 1, true
	case 19:
		return Key{Name: "ctrl-s"}, 1, true
	case 27:
		if len(data) >= 3 && data[1] == '[' {
			switch data[2] {
			case 'A':
				return Key{Name: "up"}, 3, true
			case 'B':
				return Key{Name: "down"}, 3, true
			case 'Z':
				return Key{Name: "backtab"}, 3, true
			}
		}
		return Key{Name: "esc"}, 1, true
	case 127:
		return Key{Name: "backspace"}, 1, true
	default:
		if data[0] == ' ' {
			return Key{Name: "space"}, 1, true
		}
		if data[0] >= 32 && data[0] < 127 {
			return Key{Char: rune(data[0])}, 1, true
		}
		return Key{}, 1, true
	}
}

func NewScreen(w, h int) *Screen {
	rows := make([][]rune, h)
	for y := range rows {
		rows[y] = make([]rune, w)
		for x := range rows[y] {
			rows[y][x] = ' '
		}
	}
	return &Screen{W: w, H: h, rows: rows}
}

func (s *Screen) Set(x, y int, r rune) {
	if x < 1 || y < 1 || x > s.W || y > s.H {
		return
	}
	s.rows[y-1][x-1] = r
}

func (s *Screen) Text(x, y int, text string) {
	for i, r := range []rune(text) {
		s.Set(x+i, y, r)
	}
}

func (s *Screen) Box(x, y, w, h int, title string) {
	if w < 2 || h < 2 {
		return
	}
	for i := 1; i < w-1; i++ {
		s.Set(x+i, y, '─')
		s.Set(x+i, y+h-1, '─')
	}
	for i := 1; i < h-1; i++ {
		s.Set(x, y+i, '│')
		s.Set(x+w-1, y+i, '│')
	}
	s.Set(x, y, '┌')
	s.Set(x+w-1, y, '┐')
	s.Set(x, y+h-1, '└')
	s.Set(x+w-1, y+h-1, '┘')
	if title != "" {
		for i, r := range []rune(title) {
			if i >= w-2 {
				break
			}
			s.Set(x+1+i, y, r)
		}
	}
}

func (s *Screen) String() string {
	var b strings.Builder
	for _, row := range s.rows {
		b.WriteString(string(row))
		b.WriteByte('\n')
	}
	return b.String()
}

func drawPopupBox(s *Screen, x, y, w, h int, title string, lines []string) {
	s.Box(x, y, w, h, title)
	for i, line := range lines {
		if i >= h-2 {
			break
		}
		s.Text(x+1, y+1+i, center(line, w-2))
	}
}

func center(text string, width int) string {
	runes := []rune(text)
	if len(runes) >= width {
		return string(runes[:width])
	}
	left := (width - len(runes)) / 2
	right := width - len(runes) - left
	return strings.Repeat(" ", left) + text + strings.Repeat(" ", right)
}

func truncate(text string, max int) string {
	runes := []rune(text)
	if len(runes) > max {
		runes = runes[:max]
	}
	return string(runes)
}

func padRight(text string, width int) string {
	runes := []rune(text)
	if len(runes) >= width {
		return string(runes[:width])
	}
	return text + strings.Repeat(" ", width-len(runes))
}

func parseTags(raw string) []string {
	parts := strings.Split(raw, ",")
	out := make([]string, 0, len(parts))
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part != "" {
			out = append(out, part)
		}
	}
	return out
}

func isDateInputValid(raw string) bool {
	if len(raw) > 10 {
		return false
	}
	for _, r := range raw {
		if (r < '0' || r > '9') && r != '-' {
			return false
		}
	}
	return true
}

func isDigits(raw string) bool {
	for _, r := range raw {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

func containsString(values []string, target string) bool {
	for _, value := range values {
		if value == target {
			return true
		}
	}
	return false
}

func removeString(values []string, target string) []string {
	out := values[:0]
	for _, value := range values {
		if value != target {
			out = append(out, value)
		}
	}
	return out
}

func priorityString(priority *uint16) string {
	if priority == nil {
		return ""
	}
	return strconv.Itoa(int(*priority))
}

func parseUint64(raw string) uint64 {
	n, _ := strconv.ParseUint(raw, 10, 64)
	return n
}

func parseInt64(raw string) int64 {
	n, _ := strconv.ParseInt(raw, 10, 64)
	return n
}

