use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use anyhow::{anyhow, Context, Result};
use serde::Deserialize;

use crate::cli::{BackendTypeArg, Cli};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BackendType {
    Json,
    Sqlite,
}

impl BackendType {
    pub fn as_config_str(self) -> &'static str {
        match self {
            BackendType::Json => "Json",
            BackendType::Sqlite => "Sqlite",
        }
    }
}

#[derive(Debug, Clone)]
pub struct EffectiveConfig {
    pub backend_type: BackendType,
    pub scroll_per_page: u16,
    pub sync_os_clipboard: bool,
    pub history_limit: u16,
    pub colored_tags: bool,
    pub datum_visibility: String,
    pub app_state_dir: PathBuf,
    pub export_show_confirmation: bool,
    pub external_editor_auto_save: bool,
    pub external_editor_temp_file_extension: String,
    pub json_backend_file_path: PathBuf,
    pub sqlite_backend_file_path: PathBuf,
}

impl EffectiveConfig {
    pub fn render(&self) -> String {
        let mut out = String::new();
        let _ = writeln!(out, "backend_type = {:?}", self.backend_type.as_config_str());
        let _ = writeln!(out, "scroll_per_page = {}", self.scroll_per_page);
        let _ = writeln!(out, "sync_os_clipboard = {}", self.sync_os_clipboard);
        let _ = writeln!(out, "history_limit = {}", self.history_limit);
        let _ = writeln!(out, "colored_tags = {}", self.colored_tags);
        let _ = writeln!(out, "datum_visibility = {:?}", self.datum_visibility);
        let _ = writeln!(out, "app_state_dir = {:?}", self.app_state_dir.display().to_string());
        let _ = writeln!(out);
        let _ = writeln!(out, "[export]");
        let _ = writeln!(out, "show_confirmation = {}", self.export_show_confirmation);
        let _ = writeln!(out);
        let _ = writeln!(out, "[external_editor]");
        let _ = writeln!(out, "auto_save = {}", self.external_editor_auto_save);
        let _ = writeln!(
            out,
            "temp_file_extension = {:?}",
            self.external_editor_temp_file_extension
        );
        let _ = writeln!(out);
        let _ = writeln!(out, "[json_backend]");
        let _ = writeln!(
            out,
            "file_path = {:?}",
            self.json_backend_file_path.display().to_string()
        );
        let _ = writeln!(out);
        let _ = writeln!(out, "[sqlite_backend]");
        let _ = writeln!(
            out,
            "file_path = {:?}",
            self.sqlite_backend_file_path.display().to_string()
        );
        out
    }
}

#[derive(Debug, Clone)]
pub enum ConfigTarget {
    DefaultDirectory(PathBuf),
    CustomDirectory(PathBuf),
    CustomFile(PathBuf),
}

#[derive(Debug, Clone, Deserialize)]
struct RawConfig {
    #[serde(default)]
    backend_type: Option<ConfigBackendType>,
    #[serde(default)]
    scroll_per_page: Option<u16>,
    #[serde(default)]
    sync_os_clipboard: Option<bool>,
    #[serde(default)]
    history_limit: Option<u16>,
    #[serde(default)]
    colored_tags: Option<bool>,
    #[serde(default)]
    datum_visibility: Option<String>,
    #[serde(default)]
    app_state_dir: Option<PathBuf>,
    #[serde(default)]
    export: Option<RawExportConfig>,
    #[serde(default)]
    external_editor: Option<RawExternalEditorConfig>,
    #[serde(default)]
    json_backend: Option<RawBackendPathConfig>,
    #[serde(default)]
    sqlite_backend: Option<RawBackendPathConfig>,
}

#[derive(Debug, Clone, Deserialize)]
enum ConfigBackendType {
    Json,
    Sqlite,
}

#[derive(Debug, Clone, Deserialize)]
struct RawExportConfig {
    #[serde(default)]
    show_confirmation: Option<bool>,
}

#[derive(Debug, Clone, Deserialize)]
struct RawExternalEditorConfig {
    #[serde(default)]
    auto_save: Option<bool>,
    #[serde(default)]
    temp_file_extension: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
struct RawBackendPathConfig {
    #[serde(default)]
    file_path: Option<PathBuf>,
}

pub fn load_effective_config(custom_path: Option<&PathBuf>, cli: &Cli) -> Result<EffectiveConfig> {
    let target = resolve_config_target(custom_path)?;
    let raw = load_raw_config(&target)?;
    Ok(apply_cli_overrides(defaults().merge(raw), cli))
}

pub fn resolve_config_target(custom_path: Option<&PathBuf>) -> Result<ConfigTarget> {
    match custom_path {
        None => Ok(ConfigTarget::DefaultDirectory(default_config_dir())),
        Some(path) if !path.exists() => Err(anyhow!(
            "Provided custom directory doesn't exit. Path: {}",
            path.display()
        )),
        Some(path) if path.is_dir() => Ok(ConfigTarget::CustomDirectory(path.clone())),
        Some(path) => Ok(ConfigTarget::CustomFile(path.clone())),
    }
}

fn load_raw_config(target: &ConfigTarget) -> Result<Option<RawConfig>> {
    let path = match target {
        ConfigTarget::DefaultDirectory(dir) | ConfigTarget::CustomDirectory(dir) => {
            let path = dir.join("config.toml");
            if !path.exists() {
                return Ok(None);
            }
            path
        }
        ConfigTarget::CustomFile(file) => file.clone(),
    };

    let raw = std::fs::read_to_string(&path).with_context(|| "Failed to read configuration file")?;
    toml::from_str::<RawConfig>(&raw)
        .map(Some)
        .map_err(|err| anyhow!("Failed to read configuration file. Error infos: {err}"))
}

#[derive(Debug, Clone)]
struct Defaults {
    backend_type: BackendType,
    scroll_per_page: u16,
    sync_os_clipboard: bool,
    history_limit: u16,
    colored_tags: bool,
    datum_visibility: String,
    app_state_dir: PathBuf,
    export_show_confirmation: bool,
    external_editor_auto_save: bool,
    external_editor_temp_file_extension: String,
    json_backend_file_path: PathBuf,
    sqlite_backend_file_path: PathBuf,
}

impl Defaults {
    fn merge(self, raw: Option<RawConfig>) -> EffectiveConfig {
        let mut cfg = EffectiveConfig {
            backend_type: self.backend_type,
            scroll_per_page: self.scroll_per_page,
            sync_os_clipboard: self.sync_os_clipboard,
            history_limit: self.history_limit,
            colored_tags: self.colored_tags,
            datum_visibility: self.datum_visibility,
            app_state_dir: self.app_state_dir,
            export_show_confirmation: self.export_show_confirmation,
            external_editor_auto_save: self.external_editor_auto_save,
            external_editor_temp_file_extension: self.external_editor_temp_file_extension,
            json_backend_file_path: self.json_backend_file_path,
            sqlite_backend_file_path: self.sqlite_backend_file_path,
        };

        if let Some(raw) = raw {
            if let Some(backend_type) = raw.backend_type {
                cfg.backend_type = match backend_type {
                    ConfigBackendType::Json => BackendType::Json,
                    ConfigBackendType::Sqlite => BackendType::Sqlite,
                };
            }
            if let Some(value) = raw.scroll_per_page {
                cfg.scroll_per_page = value;
            }
            if let Some(value) = raw.sync_os_clipboard {
                cfg.sync_os_clipboard = value;
            }
            if let Some(value) = raw.history_limit {
                cfg.history_limit = value;
            }
            if let Some(value) = raw.colored_tags {
                cfg.colored_tags = value;
            }
            if let Some(value) = raw.datum_visibility {
                cfg.datum_visibility = value;
            }
            if let Some(value) = raw.app_state_dir {
                cfg.app_state_dir = value;
            }
            if let Some(export) = raw.export.and_then(|value| value.show_confirmation) {
                cfg.export_show_confirmation = export;
            }
            if let Some(value) = raw.external_editor.as_ref().and_then(|value| value.auto_save) {
                cfg.external_editor_auto_save = value;
            }
            if let Some(value) = raw
                .external_editor
                .and_then(|value| value.temp_file_extension)
            {
                cfg.external_editor_temp_file_extension = value;
            }
            if let Some(value) = raw.json_backend.and_then(|value| value.file_path) {
                cfg.json_backend_file_path = value;
            }
            if let Some(value) = raw.sqlite_backend.and_then(|value| value.file_path) {
                cfg.sqlite_backend_file_path = value;
            }
        }

        cfg
    }
}

fn apply_cli_overrides(mut cfg: EffectiveConfig, cli: &Cli) -> EffectiveConfig {
    if let Some(path) = &cli.json_file_path {
        cfg.json_backend_file_path = path.clone();
        cfg.backend_type = BackendType::Json;
    }
    if let Some(path) = &cli.sqlite_file_path {
        cfg.sqlite_backend_file_path = path.clone();
        cfg.backend_type = BackendType::Sqlite;
    }
    if let Some(backend_type) = cli.backend_type {
        cfg.backend_type = match backend_type {
            BackendTypeArg::Json => BackendType::Json,
            BackendTypeArg::Sqlite => BackendType::Sqlite,
        };
    }
    if cli.json_file_path.is_some() {
        cfg.backend_type = BackendType::Json;
    }
    if cli.sqlite_file_path.is_some() {
        cfg.backend_type = BackendType::Sqlite;
    }
    cfg
}

fn defaults() -> Defaults {
    let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/"));
    Defaults {
        backend_type: BackendType::Sqlite,
        scroll_per_page: 5,
        sync_os_clipboard: false,
        history_limit: 10,
        colored_tags: true,
        datum_visibility: "show".to_string(),
        app_state_dir: home.join(".local/state/tui-journal"),
        export_show_confirmation: true,
        external_editor_auto_save: false,
        external_editor_temp_file_extension: "txt".to_string(),
        json_backend_file_path: home.join("tui-journal/entries.json"),
        sqlite_backend_file_path: home.join("tui-journal/entries.db"),
    }
}

fn default_config_dir() -> PathBuf {
    let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("/"));
    home.join(".config/tui-journal")
}

