use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{anyhow, Context, Result};
use chrono::{DateTime, NaiveDate, Utc};
use rusqlite::{params, Connection};
use serde::{Deserialize, Serialize};

use crate::config::{BackendType, EffectiveConfig};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    pub id: u64,
    pub date: NaiveDate,
    pub title: String,
    pub content: String,
    pub tags: Vec<String>,
    pub priority: Option<u16>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ImportedTransfer {
    pub version: u16,
    pub entries: Vec<ImportedEntry>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ImportedEntry {
    pub id: u64,
    #[serde(with = "json_date")]
    pub date: NaiveDate,
    pub title: String,
    pub content: String,
    #[serde(default)]
    pub tags: Vec<String>,
    pub priority: Option<u16>,
}

#[derive(Debug, Clone)]
pub enum BackendStore {
    Json(JsonStore),
    Sqlite(SqliteStore),
}

impl BackendStore {
    pub fn from_effective_config(config: &EffectiveConfig) -> Result<Self> {
        match config.backend_type {
            BackendType::Json => Ok(Self::Json(JsonStore {
                path: config.json_backend_file_path.clone(),
            })),
            BackendType::Sqlite => Ok(Self::Sqlite(SqliteStore::new(
                config.sqlite_backend_file_path.clone(),
            )?)),
        }
    }

    pub fn load_entries(&self) -> Result<Vec<Entry>> {
        match self {
            BackendStore::Json(store) => store.load_entries(),
            BackendStore::Sqlite(store) => store.load_entries(),
        }
    }

    pub fn create_entry(
        &self,
        title: String,
        date: NaiveDate,
        priority: Option<u16>,
        tags: Vec<String>,
    ) -> Result<Entry> {
        match self {
            BackendStore::Json(store) => store.create_entry(title, date, priority, tags),
            BackendStore::Sqlite(store) => store.create_entry(title, date, priority, tags),
        }
    }

    pub fn update_entry_metadata(&self, entry: &Entry) -> Result<()> {
        match self {
            BackendStore::Json(store) => store.update_entry(entry),
            BackendStore::Sqlite(store) => store.update_entry(entry),
        }
    }

    pub fn update_entry_content(&self, id: u64, content: &str) -> Result<()> {
        match self {
            BackendStore::Json(store) => store.update_content(id, content),
            BackendStore::Sqlite(store) => store.update_content(id, content),
        }
    }

    pub fn delete_entry(&self, id: u64) -> Result<()> {
        match self {
            BackendStore::Json(store) => store.delete_entry(id),
            BackendStore::Sqlite(store) => store.delete_entry(id),
        }
    }

    pub fn assign_priority(&self, priority: u16) -> Result<()> {
        match self {
            BackendStore::Json(store) => store.assign_priority(priority),
            BackendStore::Sqlite(store) => store.assign_priority(priority),
        }
    }

    pub fn import_entries(&self, entries: &[ImportedEntry]) -> Result<()> {
        match self {
            BackendStore::Json(store) => store.import_entries(entries),
            BackendStore::Sqlite(store) => store.import_entries(entries),
        }
    }
}

#[derive(Debug, Clone)]
pub struct JsonStore {
    path: PathBuf,
}

impl JsonStore {
    fn load_entries(&self) -> Result<Vec<Entry>> {
        if !self.path.exists() {
            return Ok(Vec::new());
        }
        let raw = fs::read_to_string(&self.path)?;
        let stored: Vec<JsonEntry> = serde_json::from_str(&raw)?;
        Ok(stored.into_iter().map(Entry::from).collect())
    }

    fn save_entries(&self, entries: &[Entry]) -> Result<()> {
        let json: Vec<JsonEntry> = entries.iter().cloned().map(JsonEntry::from).collect();
        let raw = serde_json::to_string(&json)?;
        fs::write(&self.path, raw)?;
        Ok(())
    }

    fn create_entry(
        &self,
        title: String,
        date: NaiveDate,
        priority: Option<u16>,
        tags: Vec<String>,
    ) -> Result<Entry> {
        let mut entries = self.load_entries()?;
        let id = entries.iter().map(|entry| entry.id).max().map_or(0, |id| id + 1);
        let entry = Entry {
            id,
            date,
            title,
            content: String::new(),
            tags,
            priority,
        };
        entries.push(entry.clone());
        self.save_entries(&entries)?;
        Ok(entry)
    }

    fn update_entry(&self, updated: &Entry) -> Result<()> {
        let mut entries = self.load_entries()?;
        if let Some(entry) = entries.iter_mut().find(|entry| entry.id == updated.id) {
            *entry = updated.clone();
            self.save_entries(&entries)?;
        }
        Ok(())
    }

    fn update_content(&self, id: u64, content: &str) -> Result<()> {
        let mut entries = self.load_entries()?;
        if let Some(entry) = entries.iter_mut().find(|entry| entry.id == id) {
            entry.content = content.to_string();
            self.save_entries(&entries)?;
        }
        Ok(())
    }

    fn delete_entry(&self, id: u64) -> Result<()> {
        let mut entries = self.load_entries()?;
        entries.retain(|entry| entry.id != id);
        self.save_entries(&entries)
    }

    fn assign_priority(&self, priority: u16) -> Result<()> {
        let mut entries = self.load_entries()?;
        for entry in &mut entries {
            if entry.priority.is_none() {
                entry.priority = Some(priority);
            }
        }
        self.save_entries(&entries)
    }

    fn import_entries(&self, imported: &[ImportedEntry]) -> Result<()> {
        let mut entries = self.load_entries()?;
        let mut next_id = entries.iter().map(|entry| entry.id).max().map_or(0, |id| id + 1);
        for imported_entry in imported {
            entries.push(Entry {
                id: next_id,
                date: imported_entry.date,
                title: imported_entry.title.clone(),
                content: imported_entry.content.clone(),
                tags: imported_entry.tags.clone(),
                priority: imported_entry.priority,
            });
            next_id += 1;
        }
        self.save_entries(&entries)
    }
}

#[derive(Debug, Clone)]
pub struct SqliteStore {
    path: PathBuf,
}

impl SqliteStore {
    pub fn new(path: PathBuf) -> Result<Self> {
        let store = Self { path };
        store.initialize()?;
        Ok(store)
    }

    fn initialize(&self) -> Result<()> {
        let conn = self.open_connection()?;
        conn.execute_batch(
            r#"
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _sqlx_migrations (
    version BIGINT PRIMARY KEY,
    description TEXT NOT NULL,
    installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    success BOOLEAN NOT NULL,
    checksum BLOB NOT NULL,
    execution_time BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS entries
(
  id        INTEGER PRIMARY KEY  NOT NULL,
  title     TEXT                 NOT NULL,
  date      DATE                 NOT NULL,
  content   TEXT
, priority INTEGER DEFAULT NULL);
CREATE TABLE IF NOT EXISTS tags (
  entry_id INTEGER NOT NULL,
  tag TEXT NOT NULL,
  PRIMARY KEY (entry_id, tag),
  FOREIGN KEY (entry_id) REFERENCES entries (id) ON DELETE CASCADE
);
"#,
        )?;

        let migration_rows = [
            (
                20230509041613_i64,
                "init entries",
                vec![
                    0xa9, 0xb9, 0x62, 0xe0, 0x74, 0xe5, 0x6d, 0xb0, 0xfb, 0xfb, 0xcf, 0x48,
                    0x74, 0xed, 0x6d, 0x1e, 0x8d, 0x94, 0x31, 0x3c, 0x9c, 0x01, 0x22, 0x24,
                    0x74, 0x65, 0xcc, 0x26, 0x05, 0x7a, 0xd3, 0x63, 0x52, 0x35, 0xb2, 0x08,
                    0x70, 0x3d, 0xb8, 0xa0, 0x84, 0x3a, 0x8b, 0xc1, 0x6c, 0xd5, 0x06, 0x85,
                ],
                217287_i64,
            ),
            (
                20230613041405_i64,
                "add tags",
                vec![
                    0xe0, 0xeb, 0x5f, 0xd4, 0xd0, 0x92, 0xc8, 0x2c, 0xb2, 0xbd, 0x45, 0x28,
                    0xce, 0x27, 0xfe, 0x9c, 0x03, 0x7f, 0x04, 0x52, 0x45, 0xac, 0x9f, 0x12,
                    0x35, 0xee, 0x2c, 0xef, 0x07, 0xc7, 0x54, 0x43, 0xe8, 0xfe, 0xc9, 0x8c,
                    0x3a, 0x5f, 0x05, 0x62, 0xc6, 0x41, 0xb1, 0xbc, 0x53, 0x01, 0xf3, 0x19,
                ],
                267302_i64,
            ),
            (
                20240104160740_i64,
                "entries priorities",
                vec![
                    0x4d, 0xc4, 0xe4, 0xc3, 0xa2, 0xcd, 0x7a, 0xdf, 0x8c, 0xa6, 0xee, 0x6c,
                    0xca, 0x5a, 0x84, 0xea, 0xa9, 0x29, 0xbb, 0xb9, 0xc4, 0x96, 0x9a, 0xf5,
                    0xbc, 0x18, 0x1a, 0x99, 0x20, 0x95, 0xe6, 0x1a, 0xa1, 0x56, 0xda, 0xb7,
                    0x67, 0x18, 0x43, 0x7f, 0xcc, 0xd9, 0x9e, 0x7f, 0xa1, 0xa7, 0x5f, 0x7c,
                ],
                321234_i64,
            ),
        ];
        for (version, description, checksum, execution_time) in migration_rows {
            conn.execute(
                "INSERT OR IGNORE INTO _sqlx_migrations (version, description, success, checksum, execution_time) VALUES (?1, ?2, 1, ?3, ?4)",
                params![version, description, checksum, execution_time],
            )?;
        }
        Ok(())
    }

    fn open_connection(&self) -> Result<Connection> {
        let conn = Connection::open(&self.path)?;
        conn.pragma_update(None, "foreign_keys", "ON")?;
        Ok(conn)
    }

    fn load_entries(&self) -> Result<Vec<Entry>> {
        let conn = self.open_connection()?;
        let mut stmt = conn.prepare(
            "SELECT id, title, date, COALESCE(content, ''), priority FROM entries ORDER BY id ASC",
        )?;
        let mut rows = stmt.query([])?;
        let mut entries = Vec::new();
        while let Some(row) = rows.next()? {
            let id: i64 = row.get(0)?;
            let title: String = row.get(1)?;
            let date_str: String = row.get(2)?;
            let content: String = row.get(3)?;
            let priority: Option<u16> = row.get(4)?;
            let tags = self.load_tags_for(id as u64)?;
            entries.push(Entry {
                id: id as u64,
                date: parse_any_date(&date_str)?,
                title,
                content,
                tags,
                priority,
            });
        }
        Ok(entries)
    }

    fn load_tags_for(&self, entry_id: u64) -> Result<Vec<String>> {
        let conn = self.open_connection()?;
        let mut stmt =
            conn.prepare("SELECT tag FROM tags WHERE entry_id = ?1 ORDER BY tag COLLATE NOCASE ASC")?;
        let tags = stmt
            .query_map([entry_id], |row| row.get::<_, String>(0))?
            .collect::<std::result::Result<Vec<_>, _>>()?;
        Ok(tags)
    }

    fn create_entry(
        &self,
        title: String,
        date: NaiveDate,
        priority: Option<u16>,
        tags: Vec<String>,
    ) -> Result<Entry> {
        let conn = self.open_connection()?;
        conn.execute(
            "INSERT INTO entries (title, date, content, priority) VALUES (?1, ?2, ?3, ?4)",
            params![title, sqlite_date_string(date), "", priority],
        )?;
        let id = conn.last_insert_rowid() as u64;
        self.replace_tags(&conn, id, &tags)?;
        Ok(Entry {
            id,
            date,
            title,
            content: String::new(),
            tags,
            priority,
        })
    }

    fn update_entry(&self, entry: &Entry) -> Result<()> {
        let conn = self.open_connection()?;
        conn.execute(
            "UPDATE entries SET title = ?1, date = ?2, content = ?3, priority = ?4 WHERE id = ?5",
            params![
                entry.title,
                sqlite_date_string(entry.date),
                entry.content,
                entry.priority,
                entry.id
            ],
        )?;
        self.replace_tags(&conn, entry.id, &entry.tags)?;
        Ok(())
    }

    fn replace_tags(&self, conn: &Connection, entry_id: u64, tags: &[String]) -> Result<()> {
        conn.execute("DELETE FROM tags WHERE entry_id = ?1", [entry_id])?;
        for tag in tags {
            conn.execute(
                "INSERT INTO tags (entry_id, tag) VALUES (?1, ?2)",
                params![entry_id, tag],
            )?;
        }
        Ok(())
    }

    fn update_content(&self, id: u64, content: &str) -> Result<()> {
        let conn = self.open_connection()?;
        conn.execute("UPDATE entries SET content = ?1 WHERE id = ?2", params![content, id])?;
        Ok(())
    }

    fn delete_entry(&self, id: u64) -> Result<()> {
        let conn = self.open_connection()?;
        conn.execute("DELETE FROM entries WHERE id = ?1", [id])?;
        Ok(())
    }

    fn assign_priority(&self, priority: u16) -> Result<()> {
        let conn = self.open_connection()?;
        conn.execute(
            "UPDATE entries SET priority = ?1 WHERE priority IS NULL",
            [priority],
        )?;
        Ok(())
    }

    fn import_entries(&self, entries: &[ImportedEntry]) -> Result<()> {
        let conn = self.open_connection()?;
        for entry in entries {
            conn.execute(
                "INSERT INTO entries (title, date, content, priority) VALUES (?1, ?2, ?3, ?4)",
                params![
                    entry.title,
                    sqlite_date_string(entry.date),
                    entry.content,
                    entry.priority
                ],
            )?;
            let id = conn.last_insert_rowid() as u64;
            self.replace_tags(&conn, id, &entry.tags)?;
        }
        Ok(())
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct JsonEntry {
    id: u64,
    #[serde(with = "json_date")]
    date: NaiveDate,
    title: String,
    content: String,
    #[serde(default)]
    tags: Vec<String>,
    priority: Option<u16>,
}

impl From<JsonEntry> for Entry {
    fn from(value: JsonEntry) -> Self {
        Entry {
            id: value.id,
            date: value.date,
            title: value.title,
            content: value.content,
            tags: value.tags,
            priority: value.priority,
        }
    }
}

impl From<Entry> for JsonEntry {
    fn from(value: Entry) -> Self {
        JsonEntry {
            id: value.id,
            date: value.date,
            title: value.title,
            content: value.content,
            tags: value.tags,
            priority: value.priority,
        }
    }
}

pub fn sort_entries(entries: &mut [Entry]) {
    entries.sort_by(|left, right| {
        right
            .date
            .cmp(&left.date)
            .then_with(|| right.priority.cmp(&left.priority))
            .then_with(|| left.id.cmp(&right.id))
    });
}

pub fn parse_any_date(value: &str) -> Result<NaiveDate> {
    DateTime::parse_from_rfc3339(value)
        .map(|dt| dt.naive_utc().date())
        .or_else(|_| NaiveDate::parse_from_str(value, "%d-%m-%Y"))
        .map_err(|err| anyhow!(err))
}

fn sqlite_date_string(date: NaiveDate) -> String {
    format!("{}T00:00:00+00:00", date.format("%Y-%m-%d"))
}

mod json_date {
    use anyhow::{anyhow, Result};
    use chrono::{DateTime, NaiveDate};
    use serde::{Deserialize, Deserializer, Serializer};

    pub fn serialize<S>(value: &NaiveDate, serializer: S) -> std::result::Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(&format!("{}T00:00:00Z", value.format("%Y-%m-%d")))
    }

    pub fn deserialize<'de, D>(deserializer: D) -> std::result::Result<NaiveDate, D::Error>
    where
        D: Deserializer<'de>,
    {
        let raw = String::deserialize(deserializer)?;
        DateTime::parse_from_rfc3339(&raw)
            .map(|dt| dt.naive_utc().date())
            .map_err(serde::de::Error::custom)
    }
}

