    fn draw_transient_popup(&self, frame: &mut Frame, popup: &TransientPopup) {
        let width = popup
            .lines
            .iter()
            .map(|line| line.len())
            .max()
            .unwrap_or(0)
            .saturating_add(4) as u16;
        let height = popup.lines.len() as u16 + 2;
        let area = centered_rect(width, height, frame.area());
        let block = Block::default().borders(Borders::ALL);
        let text = Paragraph::new(popup.lines.join("\n")).block(block).alignment(ratatui::layout::Alignment::Center);
        frame.render_widget(Clear, area);
        frame.render_widget(text, area);
    }

    fn draw_popup(&self, frame: &mut Frame, popup: &Popup) {
        match popup {
            Popup::DeleteConfirm => {
                let area = centered_rect(44, 8, frame.area());
                let text = Paragraph::new(Text::from(vec![
                    Line::from(""),
                    Line::from("     Do you want to remove the current"),
                    Line::from("                 journal?"),
                    Line::from(""),
                    Line::from("               (Y)es , (N)o"),
                    Line::from(""),
                ]))
                .block(Block::default().borders(Borders::ALL));
                frame.render_widget(Clear, area);
                frame.render_widget(text, area);
            }
            Popup::SaveConfirm => {
                let area = centered_rect(44, 8, frame.area());
                let text = Paragraph::new(Text::from(vec![
                    Line::from(""),
                    Line::from("  Do you want to save the changes on the"),
                    Line::from("             current journal?"),
                    Line::from(""),
                    Line::from("          (Y)es , (N)o , (C)ancel"),
                    Line::from(""),
                ]))
                .block(Block::default().borders(Borders::ALL));
                frame.render_widget(Clear, area);
                frame.render_widget(text, area);
            }
            Popup::Error { title, lines } => {
                let rendered = if lines.len() == 1 {
                    vec![
                        Line::from(""),
                        Line::from(lines[0].clone()),
                        Line::from(""),
                        Line::from("                   (O)k                   "),
                        Line::from(""),
                    ]
                } else {
                    let mut out = vec![Line::from("")];
                    for line in lines {
                        out.push(Line::from(center_text(line, 42)));
                    }
                    out.push(Line::from("                   (O)k                   "));
                    out.push(Line::from(""));
                    out
                };
                let area = centered_rect(44, rendered.len() as u16 + 2, frame.area());
                let text = Paragraph::new(Text::from(rendered))
                    .block(Block::default().borders(Borders::ALL).title(title.as_str()));
                frame.render_widget(Clear, area);
                frame.render_widget(text, area);
            }
        }
    }

